CREATE OR REPLACE FUNCTION public.coin_flip_pvp_only_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
BEGIN
  IF NEW.mode IS DISTINCT FROM 'vs_player' THEN
    RAISE EXCEPTION 'Player vs House mode is no longer supported.';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.escape_room_set_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
begin
  new.updated_at := now();
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.stop_commissions_on_subscription_canceled()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if new.status = 'canceled' and (old.status is null or old.status != 'canceled') then
    update public.referral_commissions set status = 'stopped', updated_at = now() where subscription_id = new.id;
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.process_all_due_referral_commissions()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_sub record;
  v_result jsonb;
  v_processed int := 0;
  v_paid int := 0;
begin
  for v_sub in
    select id from public.subscriptions where status = 'active' and next_billing_date <= current_date order by next_billing_date
  loop
    v_result := public.process_subscription_billing(v_sub.id);
    v_processed := v_processed + 1;
    if (v_result->>'commissionPaid')::boolean then
      v_paid := v_paid + 1;
    end if;
  end loop;
  return jsonb_build_object('success', true, 'processed', v_processed, 'commissionsPaid', v_paid);
end;
$function$

CREATE OR REPLACE FUNCTION public.gpay_ledger_entry(p_user_id uuid, p_event_type text, p_amount_minor bigint, p_reference text DEFAULT NULL::text, p_metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_valid_types text[] := ARRAY[
    'reward_earn', 'referral_reward', 'game_reward', 'ad_reward',
    'manual_credit', 'manual_debit', 'admin_adjustment',
    'claim_reserve', 'claim_release', 'claim_settle',
    'game_play', 'game_win'
  ];
  d_avail bigint := 0;
  d_pend bigint := 0;
  d_claimed bigint := 0;
  d_life bigint := 0;
  v_avail bigint;
  v_pend bigint;
  v_claimed bigint;
  v_life bigint;
  av_new bigint;
  pend_new bigint;
  claimed_new bigint;
  life_new bigint;
  v_ledger_id uuid;
  v_ref text := nullif(trim(COALESCE(p_reference, '')), '');
BEGIN
  IF p_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'message', 'user_id required');
  END IF;
  IF p_event_type IS NULL OR NOT (p_event_type = ANY (v_valid_types)) THEN
    RETURN jsonb_build_object('success', false, 'message', 'Invalid event_type');
  END IF;

  IF v_ref IS NOT NULL THEN
    IF EXISTS (SELECT 1 FROM public.gpay_ledger WHERE reference = v_ref) THEN
      RETURN jsonb_build_object('success', false, 'message', 'Duplicate transaction');
    END IF;
  END IF;

  IF p_event_type IN ('reward_earn', 'referral_reward', 'game_reward', 'ad_reward', 'manual_credit', 'game_win') THEN
    IF p_amount_minor IS NULL OR p_amount_minor <= 0 THEN
      RETURN jsonb_build_object('success', false, 'message', 'Amount must be positive');
    END IF;
    d_avail := p_amount_minor;
    d_life := p_amount_minor;
  ELSIF p_event_type IN ('manual_debit', 'game_play') THEN
    IF p_amount_minor IS NULL OR p_amount_minor >= 0 THEN
      RETURN jsonb_build_object('success', false, 'message', 'Debit requires negative amount_minor');
    END IF;
    d_avail := p_amount_minor;
  ELSIF p_event_type = 'admin_adjustment' THEN
    IF p_amount_minor IS NULL OR p_amount_minor = 0 THEN
      RETURN jsonb_build_object('success', false, 'message', 'admin_adjustment amount must be non-zero');
    END IF;
    d_avail := p_amount_minor;
    IF p_amount_minor > 0 THEN
      d_life := p_amount_minor;
    END IF;
  ELSIF p_event_type IN ('claim_reserve', 'claim_release', 'claim_settle') THEN
    IF p_amount_minor IS NULL OR p_amount_minor <= 0 THEN
      RETURN jsonb_build_object('success', false, 'message', 'claim amount must be positive');
    END IF;
    IF p_event_type = 'claim_reserve' THEN
      d_avail := -p_amount_minor;
      d_pend := p_amount_minor;
    ELSIF p_event_type = 'claim_release' THEN
      d_avail := p_amount_minor;
      d_pend := -p_amount_minor;
    ELSE
      d_pend := -p_amount_minor;
      d_claimed := p_amount_minor;
    END IF;
  END IF;

  INSERT INTO public.gpay_balances (user_id, updated_at)
  VALUES (p_user_id, now())
  ON CONFLICT (user_id) DO NOTHING;

  SELECT available_minor, pending_claim_minor, claimed_lifetime_minor, lifetime_earned_minor
  INTO v_avail, v_pend, v_claimed, v_life
  FROM public.gpay_balances
  WHERE user_id = p_user_id
  FOR UPDATE;

  IF v_avail IS NULL THEN
    RETURN jsonb_build_object('success', false, 'message', 'GPay balance row not found');
  END IF;

  av_new := v_avail + d_avail;
  pend_new := v_pend + d_pend;
  claimed_new := v_claimed + d_claimed;
  life_new := v_life + d_life;

  IF av_new < 0 OR pend_new < 0 OR claimed_new < 0 OR life_new < 0 THEN
    RETURN jsonb_build_object('success', false, 'message', 'Insufficient balance or invalid state');
  END IF;

  INSERT INTO public.gpay_ledger (
    user_id,
    event_type,
    amount_minor,
    delta_available_minor,
    delta_pending_claim_minor,
    delta_claimed_lifetime_minor,
    delta_lifetime_earned_minor,
    available_after_minor,
    pending_claim_after_minor,
    claimed_lifetime_after_minor,
    lifetime_earned_after_minor,
    reference,
    metadata
  ) VALUES (
    p_user_id,
    p_event_type,
    p_amount_minor,
    d_avail,
    d_pend,
    d_claimed,
    d_life,
    av_new,
    pend_new,
    claimed_new,
    life_new,
    v_ref,
    COALESCE(p_metadata, '{}'::jsonb)
  )
  RETURNING id INTO v_ledger_id;

  UPDATE public.gpay_balances
  SET
    available_minor = av_new,
    pending_claim_minor = pend_new,
    claimed_lifetime_minor = claimed_new,
    lifetime_earned_minor = life_new,
    updated_at = now()
  WHERE user_id = p_user_id;

  RETURN jsonb_build_object(
    'success', true,
    'ledger_id', v_ledger_id,
    'available_minor', av_new,
    'pending_claim_minor', pend_new,
    'claimed_lifetime_minor', claimed_new,
    'lifetime_earned_minor', life_new
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.complete_ad_session_with_platform_protection(p_user_id uuid, p_session_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_session record;
  v_ad record;
  v_pct numeric;
  v_reward bigint;
  v_revenue bigint;
BEGIN
  SELECT * INTO v_session FROM public.ad_sessions WHERE id = p_session_id FOR UPDATE;
  IF v_session IS NULL THEN RETURN jsonb_build_object('success', false, 'message', 'Invalid session'); END IF;
  IF v_session.user_id != p_user_id THEN RETURN jsonb_build_object('success', false, 'message', 'Unauthorized'); END IF;
  IF v_session.reward_given THEN RETURN jsonb_build_object('success', false, 'message', 'Reward already issued'); END IF;
  IF (v_session.start_time + (SELECT duration_seconds FROM public.ads WHERE id = v_session.ad_id) * interval '1 second') > now() THEN
    RETURN jsonb_build_object('success', false, 'message', 'Timer not complete');
  END IF;

  SELECT * INTO v_ad FROM public.ads WHERE id = v_session.ad_id;
  IF v_ad IS NULL THEN RETURN jsonb_build_object('success', false, 'message', 'Ad not found'); END IF;

  SELECT COALESCE((SELECT ad_reward_percent FROM public.platform_settings WHERE id = 'default' LIMIT 1), 40) INTO v_pct;
  v_reward := round(v_ad.advertiser_price * v_pct / 100)::bigint;
  v_revenue := v_ad.advertiser_price;

  PERFORM public.platform_record_revenue(v_revenue, 'ad');
  PERFORM public.platform_record_payout(v_reward, 'ad');

  UPDATE public.ad_sessions SET completed = true, reward_given = true WHERE id = p_session_id;
  UPDATE public.users SET balance = balance + v_reward, updated_at = now() WHERE id = p_user_id;
  INSERT INTO public.earnings (user_id, amount, source, reference_id) VALUES (p_user_id, v_reward, 'ad', p_session_id);
  INSERT INTO public.transactions (user_id, type, amount, status, description, reference_id)
  VALUES (p_user_id, 'earning', v_reward, 'completed', 'Ad reward', p_session_id);

  RETURN jsonb_build_object('success', true, 'rewardCents', v_reward);
EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('success', false, 'message', SQLERRM);
END;
$function$

CREATE OR REPLACE FUNCTION public.sync_balance_on_transaction()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  amt numeric;
begin
  if new.status is distinct from 'completed' then
    return new;
  end if;
  if tg_op = 'UPDATE' and old.status = 'completed' then
    return new; -- already applied
  end if;

  amt := coalesce(new.amount, 0);
  if new.user_id is null then
    return new;
  end if;

  if lower(coalesce(new.type, '')) = 'withdrawal' then
    update public.users set balance = coalesce(balance, 0) - amt where id = new.user_id;
  else
    update public.users set balance = coalesce(balance, 0) + amt where id = new.user_id;
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.check_platform_balance_integrity()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
BEGIN
  IF NEW.total_rewards_paid_cents > NEW.total_revenue_cents THEN
    RAISE EXCEPTION 'Platform integrity: total_rewards_paid (%) cannot exceed total_revenue (%)',
      NEW.total_rewards_paid_cents, NEW.total_revenue_cents;
  END IF;
  IF NEW.balance_cents < 0 THEN
    RAISE EXCEPTION 'Platform balance cannot be negative';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.celo_post_entry_atomic(p_room_id uuid, p_user_id uuid, p_amount integer, p_reference text, p_description text DEFAULT 'C-Lo table entry'::text, p_ledger_type text DEFAULT 'celo_entry'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_room public.celo_rooms%ROWTYPE;
  v_player public.celo_room_players%ROWTYPE;
  v_now timestamptz := now();
  v_status text;
  v_desc text := COALESCE(NULLIF(trim(p_description), ''), 'C-Lo table entry');
  v_type text := COALESCE(NULLIF(trim(p_ledger_type), ''), 'celo_entry');
  v_min_entry integer;
  v_max_bank integer;
BEGIN
  IF p_room_id IS NULL OR p_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'message', 'room_id and user_id required');
  END IF;
  IF p_amount IS NULL OR p_amount <= 0 THEN
    RETURN jsonb_build_object('success', false, 'message', 'amount must be positive');
  END IF;
  IF p_reference IS NULL OR trim(p_reference) = '' THEN
    RETURN jsonb_build_object('success', false, 'message', 'reference required');
  END IF;

  IF EXISTS (SELECT 1 FROM public.coin_transactions WHERE reference = p_reference) THEN
    RETURN jsonb_build_object('success', false, 'message', 'Duplicate transaction');
  END IF;

  SELECT *
  INTO v_room
  FROM public.celo_rooms
  WHERE id = p_room_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'message', 'Room not found');
  END IF;

  v_min_entry := GREATEST(
    500,
    COALESCE(v_room.minimum_entry_sc, v_room.min_bet_cents, 100)
  );
  v_max_bank := GREATEST(
    0,
    COALESCE(v_room.current_bank_sc, v_room.current_bank_cents, 0)::integer
  );

  IF p_amount < v_min_entry THEN
    RETURN jsonb_build_object('success', false, 'message', 'Bet must be at least the room minimum.');
  END IF;
  IF v_max_bank <= 0 THEN
    RETURN jsonb_build_object('success', false, 'message', 'Table bank is empty.');
  END IF;
  IF p_amount > v_max_bank THEN
    RETURN jsonb_build_object('success', false, 'message', 'Bet cannot exceed the current bank.');
  END IF;

  v_status := trim(COALESCE(v_room.status, ''));
  IF v_status = 'rolling' OR v_status = 'completed' THEN
    RETURN jsonb_build_object('success', false, 'message', 'Cannot post entry for this room state');
  END IF;
  IF v_status <> ALL (ARRAY['waiting', 'active', 'entry_phase']) THEN
    RETURN jsonb_build_object('success', false, 'message', 'Entries cannot be posted in this room state');
  END IF;

  IF v_room.banker_id IS NOT NULL AND v_room.banker_id = p_user_id THEN
    RETURN jsonb_build_object('success', false, 'message', 'The banker cannot post a player entry');
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.celo_rounds r
    WHERE r.room_id = p_room_id
      AND r.status IN ('banker_rolling', 'player_rolling', 'betting')
    LIMIT 1
  ) THEN
    RETURN jsonb_build_object('success', false, 'message', 'A round is already in progress');
  END IF;

  SELECT *
  INTO v_player
  FROM public.celo_room_players
  WHERE room_id = p_room_id
    AND user_id = p_user_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'message', 'You are not seated at this table');
  END IF;

  IF lower(trim(COALESCE(v_player.role, ''))) <> 'player' THEN
    RETURN jsonb_build_object('success', false, 'message', 'Only players in a player seat can post an entry');
  END IF;

  IF v_player.entry_posted IS TRUE
     OR COALESCE(v_player.stake_amount_sc, 0) > 0
     OR COALESCE(v_player.entry_sc, 0) > 0
     OR COALESCE(v_player.bet_cents, 0) > 0 THEN
    RETURN jsonb_build_object('success', false, 'message', 'You already posted an entry for this round');
  END IF;

  UPDATE public.users u
  SET gpay_coins = u.gpay_coins - p_amount
  WHERE u.id = p_user_id
    AND u.gpay_coins >= p_amount;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'message', 'Insufficient GPay Coins for this entry');
  END IF;

  INSERT INTO public.coin_transactions (
    user_id,
    type,
    gold_coins,
    gpay_coins,
    description,
    reference
  )
  VALUES (
    p_user_id,
    v_type,
    0,
    -p_amount,
    v_desc,
    p_reference
  );

  UPDATE public.celo_room_players
  SET
    entry_sc = p_amount,
    bet_cents = p_amount,
    entry_posted = true,
    stake_amount_sc = p_amount,
    status = 'active',
    player_seat_status = 'active'
  WHERE room_id = p_room_id
    AND user_id = p_user_id;

  IF v_status IN ('waiting', 'entry_phase') THEN
    UPDATE public.celo_rooms
    SET
      status = CASE WHEN v_status = 'waiting' THEN 'active' ELSE 'entry_phase' END,
      last_activity = v_now
    WHERE id = p_room_id;
  ELSE
    UPDATE public.celo_rooms
    SET last_activity = v_now
    WHERE id = p_room_id;
  END IF;

  RETURN jsonb_build_object('success', true);
END;
$function$

CREATE OR REPLACE FUNCTION public.celo_next_free_player_seat(p_room_id uuid, p_cap integer)
 RETURNS integer
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
DECLARE
  cap integer := GREATEST(2, LEAST(99, COALESCE(NULLIF(p_cap, 0), 10)));
  s integer;
BEGIN
  FOR s IN 1..(cap - 1) LOOP
    IF NOT EXISTS (
      SELECT 1
      FROM public.celo_room_players crp
      WHERE crp.room_id = p_room_id
        AND crp.seat_number IS NOT NULL
        AND crp.seat_number = s
    ) THEN
      RETURN s;
    END IF;
  END LOOP;
  RETURN 1;
END;
$function$

CREATE OR REPLACE FUNCTION public.reject_withdrawal(p_withdrawal_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_row public.withdrawals%rowtype;
  v_ref text;
  v_result jsonb;
begin
  select * into v_row from public.withdrawals where id = p_withdrawal_id for update;
  if v_row is null then
    return jsonb_build_object('success', false, 'message', 'Withdrawal not found');
  end if;
  if v_row.status != 'pending' then
    return jsonb_build_object('success', false, 'message', 'Only pending withdrawals can be rejected');
  end if;

  v_ref := 'withdrawal_reject_' || p_withdrawal_id;
  v_result := public.wallet_ledger_entry(v_row.user_id, 'admin_adjustment', v_row.amount, v_ref);
  if not (v_result->>'success')::boolean then
    return jsonb_build_object('success', false, 'message', coalesce(v_result->>'message', 'Ledger credit failed'));
  end if;

  update public.users
  set withdrawable_balance = withdrawable_balance + v_row.amount,
      pending_balance = pending_balance - v_row.amount,
      updated_at = now()
  where id = v_row.user_id;

  update public.withdrawals set status = 'rejected' where id = p_withdrawal_id;

  update public.transactions
  set status = 'rejected', description = 'Withdrawal rejected - balance refunded'
  where reference_id = p_withdrawal_id and type = 'withdrawal';

  return jsonb_build_object('success', true);
end;
$function$

CREATE OR REPLACE FUNCTION public.process_game_loss(p_user_id uuid, p_amount_cents integer, p_reference text, p_description text DEFAULT NULL::text, p_ledger_type text DEFAULT 'game_loss'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_desc text;
  v_type text;
BEGIN
  IF p_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'message', 'user_id required');
  END IF;
  IF p_amount_cents IS NULL OR p_amount_cents <= 0 THEN
    RETURN jsonb_build_object('success', false, 'message', 'Invalid amount');
  END IF;
  IF p_reference IS NULL OR trim(p_reference) = '' THEN
    RETURN jsonb_build_object('success', false, 'message', 'reference required');
  END IF;

  v_desc := COALESCE(NULLIF(trim(p_description), ''), 'Game loss');
  v_type := COALESCE(NULLIF(trim(p_ledger_type), ''), 'game_loss');

  IF EXISTS (SELECT 1 FROM public.coin_transactions WHERE reference = p_reference) THEN
    RETURN jsonb_build_object('success', false, 'message', 'Duplicate transaction');
  END IF;

  IF NOT EXISTS (SELECT 1 FROM public.users WHERE id = p_user_id) THEN
    RETURN jsonb_build_object('success', false, 'message', 'User not found');
  END IF;

  UPDATE public.users u
  SET gpay_coins = u.gpay_coins - p_amount_cents
  WHERE u.id = p_user_id
    AND u.gpay_coins >= p_amount_cents;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'message', 'Insufficient gpay coins');
  END IF;

  INSERT INTO public.coin_transactions (user_id, type, gold_coins, gpay_coins, description, reference)
  VALUES (
    p_user_id,
    v_type,
    0,
    -p_amount_cents,
    v_desc,
    p_reference
  );

  RETURN jsonb_build_object('success', true);
END;
$function$

CREATE OR REPLACE FUNCTION public.garmon_ad_engage(p_user_id uuid, p_ad_id uuid, p_engagement_type text, p_duration_seconds integer DEFAULT 0, p_user_earned_dollars numeric DEFAULT 0, p_admin_earned_dollars numeric DEFAULT 0, p_advertiser_charged_dollars numeric DEFAULT 0, p_ip_address text DEFAULT NULL::text, p_device_type text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_ad record;
  v_same_ad_24h int;
  v_same_advertiser_today int;
  v_user_earned_today decimal;
  v_engagement_id uuid;
  v_earning_id uuid;
  v_cents bigint;
  v_ledger_result jsonb;
BEGIN
  -- 1) Load ad
  SELECT * INTO v_ad FROM public.garmon_ads WHERE id = p_ad_id FOR UPDATE;
  IF v_ad IS NULL THEN
    RETURN jsonb_build_object('success', false, 'message', 'Ad not found');
  END IF;
  IF v_ad.status != 'active' OR v_ad.is_active IS NOT TRUE THEN
    RETURN jsonb_build_object('success', false, 'message', 'Ad is not active');
  END IF;
  IF v_ad.remaining_budget < p_advertiser_charged_dollars THEN
    RETURN jsonb_build_object('success', false, 'message', 'Insufficient ad budget');
  END IF;

  -- 2) Same ad: max 1 per 24h
  SELECT count(*) INTO v_same_ad_24h
  FROM public.garmon_ad_engagements
  WHERE ad_id = p_ad_id AND user_id = p_user_id
    AND created_at >= now() - interval '24 hours';
  IF v_same_ad_24h > 0 THEN
    RETURN jsonb_build_object('success', false, 'message', 'Already engaged with this ad in the last 24 hours');
  END IF;

  -- 3) Same advertiser: max 3 per day
  SELECT count(*) INTO v_same_advertiser_today
  FROM public.garmon_ad_engagements e
  JOIN public.garmon_ads a ON a.id = e.ad_id
  WHERE e.user_id = p_user_id AND a.advertiser_id = v_ad.advertiser_id
    AND e.created_at >= date_trunc('day', now());
  IF v_same_advertiser_today >= 3 THEN
    RETURN jsonb_build_object('success', false, 'message', 'Max 3 engagements per advertiser per day');
  END IF;

  -- 4) User daily cap $2
  SELECT coalesce(sum(amount), 0) INTO v_user_earned_today
  FROM public.garmon_user_ad_earnings
  WHERE user_id = p_user_id AND status = 'credited'
    AND credited_at >= date_trunc('day', now());
  IF v_user_earned_today + p_user_earned_dollars > 2.0 THEN
    RETURN jsonb_build_object('success', false, 'message', 'Daily earnings limit reached');
  END IF;

  -- 5) Fraud flag check
  IF EXISTS (SELECT 1 FROM public.garmon_ad_fraud_flags WHERE user_id = p_user_id) THEN
    RETURN jsonb_build_object('success', false, 'message', 'Account flagged');
  END IF;

  -- 6) Insert engagement
  INSERT INTO public.garmon_ad_engagements (
    ad_id, user_id, engagement_type, duration_seconds,
    user_earned, admin_earned, advertiser_charged, ip_address, device_type
  ) VALUES (
    p_ad_id, p_user_id, p_engagement_type, p_duration_seconds,
    p_user_earned_dollars, p_admin_earned_dollars, p_advertiser_charged_dollars,
    p_ip_address, p_device_type
  )
  RETURNING id INTO v_engagement_id;

  -- 7) Insert user_ad_earning (credited)
  INSERT INTO public.garmon_user_ad_earnings (
    user_id, ad_id, engagement_id, amount, engagement_type, status, credited_at
  ) VALUES (
    p_user_id, p_ad_id, v_engagement_id, p_user_earned_dollars, p_engagement_type,
    'credited', now()
  )
  RETURNING id INTO v_earning_id;

  -- 8) Update ad: budget, stats, total_paid, total_admin_cut
  UPDATE public.garmon_ads SET
    remaining_budget = remaining_budget - p_advertiser_charged_dollars,
    total_paid_to_users = total_paid_to_users + p_user_earned_dollars,
    total_admin_cut = total_admin_cut + p_admin_earned_dollars,
    views = views + CASE WHEN p_engagement_type IN ('view','banner_view') THEN 1 ELSE 0 END,
    clicks = clicks + CASE WHEN p_engagement_type = 'click' THEN 1 ELSE 0 END,
    follows = follows + CASE WHEN p_engagement_type = 'follow' THEN 1 ELSE 0 END,
    shares = shares + CASE WHEN p_engagement_type = 'share' THEN 1 ELSE 0 END,
    status = CASE WHEN remaining_budget - p_advertiser_charged_dollars <= 0 THEN 'paused' ELSE status END,
    is_active = CASE WHEN remaining_budget - p_advertiser_charged_dollars <= 0 THEN false ELSE is_active END,
    updated_at = now()
  WHERE id = p_ad_id;

  -- 9) Credit user wallet (cents)
  v_cents := round(p_user_earned_dollars * 100)::bigint;
  IF v_cents > 0 THEN
    v_ledger_result := public.wallet_ledger_entry(
      p_user_id,
      'ad_earning',
      v_cents,
      'garmon_engage_' || v_engagement_id::text
    );
    IF (v_ledger_result->>'success')::boolean IS NOT TRUE THEN
      -- Rollback by raising; in production you might want to compensate
      RAISE EXCEPTION 'Wallet credit failed: %', v_ledger_result->>'message';
    END IF;
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'engagementId', v_engagement_id,
    'earningId', v_earning_id,
    'userEarnedDollars', p_user_earned_dollars,
    'userEarnedCents', v_cents
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.check_username_available(candidate text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_candidate text := lower(trim(COALESCE(candidate, '')));
  v_reserved text[] := ARRAY[
    'admin', 'garmonpay', 'support', 'mod', 'moderator', 'system',
    'official', 'bishop', 'anthropic', 'claude', 'root', 'null'
  ];
BEGIN
  IF v_candidate = '' THEN
    RETURN false;
  END IF;
  IF length(v_candidate) < 3 OR length(v_candidate) > 20 THEN
    RETURN false;
  END IF;
  IF v_candidate !~ '^[a-zA-Z0-9_]+$' THEN
    RETURN false;
  END IF;
  IF v_candidate = ANY(v_reserved) THEN
    RETURN false;
  END IF;
  IF EXISTS (
    SELECT 1
    FROM public.users
    WHERE lower(username) = v_candidate
  ) THEN
    RETURN false;
  END IF;
  RETURN true;
END;
$function$

CREATE OR REPLACE FUNCTION public.garmondrop_cell(g jsonb, r integer, c integer)
 RETURNS integer
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE
  v jsonb;
BEGIN
  IF r < 0 OR r > 5 OR c < 0 OR c > 6 THEN
    RETURN -1;
  END IF;
  v := g -> r -> c;
  IF v IS NULL OR jsonb_typeof(v) = 'null' THEN
    RETURN 0;
  END IF;
  RETURN (v #>> '{}')::int;
END;
$function$

CREATE OR REPLACE FUNCTION public.garmondrop_count_dir(g jsonb, pr integer, pc integer, val integer, dr integer, dc integer)
 RETURNS integer
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE
  cnt int := 0;
  r int;
  c int;
  cell int;
BEGIN
  r := pr;
  c := pc;
  LOOP
    cell := public.garmondrop_cell(g, r, c);
    EXIT WHEN cell <> val;
    cnt := cnt + 1;
    r := r + dr;
    c := c + dc;
  END LOOP;
  RETURN cnt;
END;
$function$

CREATE OR REPLACE FUNCTION public.garmondrop_board_full(g jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE
  c int;
BEGIN
  FOR c IN 0..6 LOOP
    IF public.garmondrop_cell(g, 0, c) = 0 THEN
      RETURN false;
    END IF;
  END LOOP;
  RETURN true;
END;
$function$

CREATE OR REPLACE FUNCTION public.garmondrop_forfeit_atomic(p_room_id uuid, p_user_id uuid, p_reference text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_room public.garmondrop_rooms%ROWTYPE;
  v_now timestamptz := now();
  v_winner uuid;
  v_pot bigint;
  v_fee int;
  v_winner_payout bigint;
BEGIN
  IF p_room_id IS NULL OR p_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'message', 'room and user required');
  END IF;
  IF p_reference IS NULL OR trim(p_reference) = '' THEN
    RETURN jsonb_build_object('success', false, 'message', 'reference required');
  END IF;

  IF EXISTS (SELECT 1 FROM public.coin_transactions WHERE reference = p_reference) THEN
    SELECT * INTO v_room FROM public.garmondrop_rooms WHERE id = p_room_id;
    IF FOUND AND v_room.status = 'completed' THEN
      RETURN jsonb_build_object('success', true, 'idempotent', true, 'room', row_to_json(v_room)::jsonb);
    END IF;
    RETURN jsonb_build_object('success', false, 'message', 'Duplicate reference');
  END IF;

  SELECT * INTO v_room FROM public.garmondrop_rooms WHERE id = p_room_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'message', 'Room not found');
  END IF;

  IF v_room.status <> 'active' THEN
    RETURN jsonb_build_object('success', false, 'message', 'Game is not active');
  END IF;

  IF p_user_id <> v_room.creator_id AND p_user_id <> v_room.opponent_id THEN
    RETURN jsonb_build_object('success', false, 'message', 'Not a player in this room');
  END IF;

  v_winner := CASE WHEN p_user_id = v_room.creator_id THEN v_room.opponent_id ELSE v_room.creator_id END;
  v_pot := v_room.pot_total_minor;
  v_fee := floor(v_pot * 0.1);
  v_winner_payout := v_pot - v_fee;

  UPDATE public.users
  SET gpay_coins = gpay_coins + v_winner_payout
  WHERE id = v_winner;

  INSERT INTO public.coin_transactions (
    user_id, type, gold_coins, gpay_coins, description, reference
  ) VALUES (
    v_winner, 'garmondrop_win', 0, v_winner_payout,
    'GarmonDrop win (forfeit)', p_reference
  );

  PERFORM public.garmondrop_record_platform_fee(
    p_room_id,
    v_fee,
    v_winner,
    'garmondrop_fee_' || p_room_id::text
  );

  UPDATE public.garmondrop_rooms
  SET
    status = 'completed',
    winner_id = v_winner,
    platform_fee_minor = v_fee,
    winner_payout_minor = v_winner_payout,
    current_turn = NULL,
    completed_at = v_now,
    updated_at = v_now
  WHERE id = p_room_id;

  SELECT * INTO v_room FROM public.garmondrop_rooms WHERE id = p_room_id;
  RETURN jsonb_build_object(
    'success', true,
    'outcome', 'forfeit',
    'winner_id', v_winner,
    'room', row_to_json(v_room)::jsonb
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.garmondrop_cancel_waiting_atomic(p_room_id uuid, p_user_id uuid, p_reference text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_room public.garmondrop_rooms%ROWTYPE;
  v_amt int;
  v_now timestamptz := now();
BEGIN
  IF p_room_id IS NULL OR p_user_id IS NULL OR p_reference IS NULL OR trim(p_reference) = '' THEN
    RETURN jsonb_build_object('success', false, 'message', 'Invalid arguments');
  END IF;

  IF EXISTS (SELECT 1 FROM public.coin_transactions WHERE reference = p_reference) THEN
    RETURN jsonb_build_object('success', true, 'idempotent', true);
  END IF;

  SELECT * INTO v_room FROM public.garmondrop_rooms WHERE id = p_room_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'message', 'Room not found');
  END IF;

  IF v_room.status <> 'waiting' OR v_room.opponent_id IS NOT NULL THEN
    RETURN jsonb_build_object('success', false, 'message', 'Room cannot be cancelled');
  END IF;

  IF v_room.creator_id <> p_user_id THEN
    RETURN jsonb_build_object('success', false, 'message', 'Only the host can cancel');
  END IF;

  v_amt := v_room.entry_amount_minor;

  UPDATE public.users SET gpay_coins = gpay_coins + v_amt WHERE id = p_user_id;

  INSERT INTO public.coin_transactions (
    user_id, type, gold_coins, gpay_coins, description, reference
  ) VALUES (
    p_user_id, 'garmondrop_refund', 0, v_amt,
    'GarmonDrop cancel waiting room', p_reference
  );

  UPDATE public.garmondrop_rooms
  SET status = 'cancelled', updated_at = v_now, completed_at = v_now
  WHERE id = p_room_id;

  RETURN jsonb_build_object('success', true);
END;
$function$

CREATE OR REPLACE FUNCTION public.garmondrop_cancel_room(p_room_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_room public.garmondrop_rooms%ROWTYPE;
  v_now timestamptz := now();
  v_amt int;
  v_ref text;
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('success', false, 'message', 'Unauthorized');
  END IF;
  IF p_room_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'message', 'room_id required');
  END IF;

  SELECT * INTO v_room
  FROM public.garmondrop_rooms
  WHERE id = p_room_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'message', 'Room not found');
  END IF;

  IF v_room.creator_id <> v_uid THEN
    RETURN jsonb_build_object('success', false, 'message', 'Only the room creator can cancel');
  END IF;

  IF v_room.status = 'cancelled' THEN
    RETURN jsonb_build_object('success', true, 'idempotent', true);
  END IF;

  IF v_room.status <> 'waiting' OR v_room.opponent_id IS NOT NULL THEN
    RETURN jsonb_build_object('success', false, 'message', 'Room cannot be cancelled');
  END IF;

  v_amt := GREATEST(0, COALESCE(v_room.entry_amount_minor, 0));
  v_ref := 'garmondrop_cancel_' || p_room_id::text;

  UPDATE public.users
  SET gpay_coins = gpay_coins + v_amt
  WHERE id = v_uid;

  INSERT INTO public.coin_transactions (
    user_id, type, gold_coins, gpay_coins, description, reference
  ) VALUES (
    v_uid, 'garmondrop_refund', 0, v_amt,
    'GarmonDrop cancel waiting room', v_ref
  );

  UPDATE public.garmondrop_rooms
  SET status = 'cancelled', updated_at = v_now, completed_at = v_now
  WHERE id = p_room_id;

  RETURN jsonb_build_object('success', true);
END;
$function$

CREATE OR REPLACE FUNCTION public.coin_flip_record_platform_fee(p_game_id uuid, p_amount_gpc integer, p_winner_user_id uuid, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_amount integer := GREATEST(0, COALESCE(p_amount_gpc, 0));
  v_key text := NULLIF(trim(COALESCE(p_idempotency_key, '')), '');
  v_inserted_id uuid;
BEGIN
  IF v_amount <= 0 THEN
    RETURN jsonb_build_object('inserted', false, 'reason', 'non_positive_amount');
  END IF;
  IF p_game_id IS NULL THEN
    RETURN jsonb_build_object('inserted', false, 'reason', 'game_id_required');
  END IF;
  IF v_key IS NULL THEN
    RETURN jsonb_build_object('inserted', false, 'reason', 'idempotency_key_required');
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.platform_earnings pe WHERE pe.idempotency_key = v_key
  ) THEN
    RETURN jsonb_build_object('inserted', false, 'reason', 'duplicate_or_conflict');
  END IF;

  BEGIN
    INSERT INTO public.platform_earnings (
      source,
      source_id,
      amount_cents,
      description,
      user_id,
      idempotency_key
    )
    VALUES (
      'coinflip_platform_fee',
      p_game_id::text,
      v_amount,
      'Coin Flip PvP platform fee (10% of pot)',
      p_winner_user_id,
      v_key
    )
    RETURNING id INTO v_inserted_id;
  EXCEPTION
    WHEN unique_violation THEN
      RETURN jsonb_build_object('inserted', false, 'reason', 'duplicate_or_conflict');
  END;

  PERFORM public.platform_record_revenue(v_amount::bigint, 'coinflip_fee');

  RETURN jsonb_build_object('inserted', true, 'id', v_inserted_id, 'idempotency_key', v_key);
END;
$function$

CREATE OR REPLACE FUNCTION public.approve_withdrawal(p_withdrawal_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_row public.withdrawals%rowtype;
begin
  select * into v_row from public.withdrawals where id = p_withdrawal_id for update;
  if v_row is null then
    return jsonb_build_object('success', false, 'message', 'Withdrawal not found');
  end if;
  if v_row.status != 'pending' then
    return jsonb_build_object('success', false, 'message', 'Only pending withdrawals can be approved');
  end if;

  update public.withdrawals
  set status = 'approved', processed_at = now()
  where id = p_withdrawal_id;

  update public.users
  set pending_balance = pending_balance - v_row.amount,
      updated_at = now()
  where id = v_row.user_id;

  if coalesce(v_row.platform_fee, 0) > 0 then
    insert into public.platform_revenue (amount, source)
    values (v_row.platform_fee, 'withdrawal_fee');
  end if;

  return jsonb_build_object('success', true, 'withdrawal', to_jsonb(v_row));
end;
$function$

CREATE OR REPLACE FUNCTION public.claim_daily_reward(p_user_id uuid, p_reward_cents bigint DEFAULT 25)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_today date := current_date;
  v_last date;
begin
  if p_reward_cents is null or p_reward_cents <= 0 then
    return jsonb_build_object('success', false, 'message', 'Invalid reward');
  end if;
  select last_claim_date into v_last from public.daily_rewards where user_id = p_user_id;
  if v_last is not null and v_last >= v_today then
    return jsonb_build_object('success', false, 'message', 'Already claimed today');
  end if;
  insert into public.daily_rewards (user_id, last_claim_date, reward_amount, updated_at)
  values (p_user_id, v_today, p_reward_cents, now())
  on conflict (user_id) do update set
    last_claim_date = v_today,
    reward_amount = p_reward_cents,
    updated_at = now();
  update public.users set balance = balance + p_reward_cents, updated_at = now() where id = p_user_id;
  insert into public.transactions (user_id, type, amount, status, description)
  values (p_user_id, 'earning', p_reward_cents, 'completed', 'Daily check-in reward');
  insert into public.earnings (user_id, amount, source) values (p_user_id, p_reward_cents, 'ad');
  insert into public.platform_activities (user_id, activity_type, description, amount_cents)
  values (p_user_id, 'daily_checkin', 'Daily check-in', p_reward_cents);
  return jsonb_build_object('success', true, 'amountCents', p_reward_cents);
end;
$function$

CREATE OR REPLACE FUNCTION public.complete_ad_session_and_issue_reward(p_user_id uuid, p_session_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_session record;
  v_ad record;
  v_reward bigint;
begin
  select * into v_session from public.ad_sessions where id = p_session_id;
  if v_session is null then
    return jsonb_build_object('success', false, 'message', 'Invalid session');
  end if;
  if v_session.user_id != p_user_id then
    return jsonb_build_object('success', false, 'message', 'Unauthorized');
  end if;
  if v_session.reward_given then
    return jsonb_build_object('success', false, 'message', 'Reward already issued');
  end if;

  if (v_session.start_time + (select duration_seconds from public.ads where id = v_session.ad_id) * interval '1 second') > now() then
    return jsonb_build_object('success', false, 'message', 'Timer not complete');
  end if;

  select * into v_ad from public.ads where id = v_session.ad_id;
  if v_ad is null then
    return jsonb_build_object('success', false, 'message', 'Ad not found');
  end if;

  v_reward := v_ad.user_reward;

  update public.ad_sessions set completed = true, reward_given = true where id = p_session_id;

  update public.users set balance = balance + v_reward, updated_at = now() where id = p_user_id;

  insert into public.earnings (user_id, amount, source, reference_id)
  values (p_user_id, v_reward, 'ad', p_session_id);

  insert into public.transactions (user_id, type, amount, status, description, reference_id)
  values (p_user_id, 'earning', v_reward, 'completed', 'Ad reward', p_session_id);

  return jsonb_build_object('success', true, 'rewardCents', v_reward);
end;
$function$

CREATE OR REPLACE FUNCTION public.convert_balance_to_ad_credit(p_user_id uuid, p_amount_cents bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_balance bigint;
begin
  if p_amount_cents is null or p_amount_cents <= 0 then
    return jsonb_build_object('success', false, 'message', 'Invalid amount');
  end if;

  select balance into v_balance from public.users where id = p_user_id for update;
  if v_balance is null then
    return jsonb_build_object('success', false, 'message', 'User not found');
  end if;
  if v_balance < p_amount_cents then
    return jsonb_build_object('success', false, 'message', 'Insufficient balance');
  end if;

  update public.users
  set balance = balance - p_amount_cents,
      ad_credit_balance = ad_credit_balance + p_amount_cents,
      updated_at = now()
  where id = p_user_id;

  insert into public.transactions (user_id, type, amount, status, description)
  values (p_user_id, 'ad_credit', p_amount_cents, 'completed', 'Converted balance to ad credit');

  return jsonb_build_object('success', true, 'amountCents', p_amount_cents);
end;
$function$

CREATE OR REPLACE FUNCTION public.credit_coins_with_ledger(p_user_id uuid, p_gold_coins integer, p_gpay_coins integer, p_type text, p_description text, p_reference text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_g integer := COALESCE(p_gold_coins, 0);
  v_s integer := COALESCE(p_gpay_coins, 0);
  v_type text;
  v_desc text;
BEGIN
  IF p_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'message', 'user_id required');
  END IF;
  IF v_g = 0 AND v_s = 0 THEN
    RETURN jsonb_build_object('success', false, 'message', 'Amount cannot be zero');
  END IF;
  IF p_reference IS NULL OR trim(p_reference) = '' THEN
    RETURN jsonb_build_object('success', false, 'message', 'reference required');
  END IF;

  IF EXISTS (SELECT 1 FROM public.coin_transactions WHERE reference = p_reference) THEN
    RETURN jsonb_build_object('success', false, 'message', 'Duplicate transaction');
  END IF;

  IF NOT EXISTS (SELECT 1 FROM public.users WHERE id = p_user_id) THEN
    RETURN jsonb_build_object('success', false, 'message', 'User not found');
  END IF;

  v_type := COALESCE(NULLIF(trim(p_type), ''), 'credit');
  v_desc := COALESCE(NULLIF(trim(p_description), ''), 'Credit');

  PERFORM public.credit_coins(p_user_id, v_g, v_s);

  INSERT INTO public.coin_transactions (user_id, type, gold_coins, gpay_coins, description, reference)
  VALUES (p_user_id, v_type, v_g, v_s, v_desc, p_reference);

  RETURN jsonb_build_object('success', true);
END;
$function$

CREATE OR REPLACE FUNCTION public.garmondrop_make_move_atomic(p_room_id uuid, p_user_id uuid, p_column integer, p_expected_seq integer, p_reference text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_room public.garmondrop_rooms%ROWTYPE;
  v_now timestamptz := now();
  v_board jsonb;
  vr int;
  vc int := p_column;
  v_piece int;
  v_won boolean;
  v_full boolean;
  v_pot bigint;
  v_fee int;
  v_winner_payout bigint;
  v_winner uuid;
  v_refund_a bigint;
  v_refund_b bigint;
  v_other uuid;
BEGIN
  IF p_room_id IS NULL OR p_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'message', 'room and user required');
  END IF;
  IF p_column < 0 OR p_column > 6 THEN
    RETURN jsonb_build_object('success', false, 'message', 'Invalid column');
  END IF;
  IF p_reference IS NULL OR trim(p_reference) = '' THEN
    RETURN jsonb_build_object('success', false, 'message', 'reference required');
  END IF;

  IF EXISTS (SELECT 1 FROM public.garmondrop_moves WHERE reference = p_reference) THEN
    SELECT * INTO v_room FROM public.garmondrop_rooms WHERE id = p_room_id;
    IF FOUND THEN
      RETURN jsonb_build_object(
        'success', true,
        'idempotent', true,
        'room', row_to_json(v_room)::jsonb
      );
    END IF;
    RETURN jsonb_build_object('success', false, 'message', 'Duplicate reference');
  END IF;

  SELECT * INTO v_room FROM public.garmondrop_rooms WHERE id = p_room_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'message', 'Room not found');
  END IF;

  PERFORM public.garmondrop_fix_null_current_turn(p_room_id, v_now);
  SELECT * INTO v_room FROM public.garmondrop_rooms WHERE id = p_room_id;

  IF v_room.status <> 'active' THEN
    RETURN jsonb_build_object('success', false, 'message', 'Game is not active');
  END IF;

  IF v_room.current_turn IS DISTINCT FROM p_user_id THEN
    RETURN jsonb_build_object('success', false, 'message', 'Not your turn');
  END IF;

  IF v_room.move_seq IS DISTINCT FROM p_expected_seq THEN
    RETURN jsonb_build_object('success', false, 'message', 'Stale move sequence; refresh state');
  END IF;

  IF p_user_id <> v_room.creator_id AND p_user_id <> v_room.opponent_id THEN
    RETURN jsonb_build_object('success', false, 'message', 'Not a player in this room');
  END IF;

  v_piece := CASE WHEN p_user_id = v_room.creator_id THEN 1 ELSE 2 END;
  v_board := v_room.board_state;

  vr := -1;
  FOR rloop IN REVERSE 5..0 LOOP
    IF public.garmondrop_cell(v_board, rloop, vc) = 0 THEN
      vr := rloop;
      EXIT;
    END IF;
  END LOOP;

  IF vr < 0 THEN
    RETURN jsonb_build_object('success', false, 'message', 'Column is full');
  END IF;

  v_board := jsonb_set(v_board, ARRAY[vr::text, vc::text], to_jsonb(v_piece), true);
  v_won := public.garmondrop_has_winner(v_board, vr, vc, v_piece);
  v_full := public.garmondrop_board_full(v_board);

  INSERT INTO public.garmondrop_moves (room_id, move_seq, user_id, col, row, reference)
  VALUES (p_room_id, p_expected_seq, p_user_id, vc, vr, p_reference);

  v_pot := v_room.pot_total_minor;
  v_fee := floor(v_pot * 0.1);

  IF v_won THEN
    v_winner := p_user_id;
    v_winner_payout := v_pot - v_fee;

    UPDATE public.users
    SET gpay_coins = gpay_coins + v_winner_payout
    WHERE id = v_winner;

    INSERT INTO public.coin_transactions (
      user_id, type, gold_coins, gpay_coins, description, reference
    ) VALUES (
      v_winner, 'garmondrop_win', 0, v_winner_payout,
      'GarmonDrop win payout', 'garmondrop_win_' || p_room_id::text
    );

    PERFORM public.garmondrop_record_platform_fee(
      p_room_id,
      v_fee,
      v_winner,
      'garmondrop_fee_' || p_room_id::text
    );

    UPDATE public.garmondrop_rooms
    SET
      board_state = v_board,
      status = 'completed',
      winner_id = v_winner,
      platform_fee_minor = v_fee,
      winner_payout_minor = v_winner_payout,
      current_turn = NULL,
      move_seq = p_expected_seq + 1,
      completed_at = v_now,
      updated_at = v_now
    WHERE id = p_room_id;

    SELECT * INTO v_room FROM public.garmondrop_rooms WHERE id = p_room_id;
    RETURN jsonb_build_object(
      'success', true,
      'outcome', 'win',
      'winner_id', v_winner,
      'room', row_to_json(v_room)::jsonb
    );
  END IF;

  IF v_full THEN
    v_refund_a := (v_pot - v_fee) / 2;
    v_refund_b := (v_pot - v_fee) - v_refund_a;

    UPDATE public.users SET gpay_coins = gpay_coins + v_refund_a WHERE id = v_room.creator_id;
    UPDATE public.users SET gpay_coins = gpay_coins + v_refund_b WHERE id = v_room.opponent_id;

    INSERT INTO public.coin_transactions (
      user_id, type, gold_coins, gpay_coins, description, reference
    ) VALUES
      (v_room.creator_id, 'garmondrop_draw_refund', 0, v_refund_a,
       'GarmonDrop draw refund', 'garmondrop_draw_' || p_room_id::text || '_a'),
      (v_room.opponent_id, 'garmondrop_draw_refund', 0, v_refund_b,
       'GarmonDrop draw refund', 'garmondrop_draw_' || p_room_id::text || '_b');

    PERFORM public.garmondrop_record_platform_fee(
      p_room_id,
      v_fee,
      v_room.creator_id,
      'garmondrop_fee_' || p_room_id::text
    );

    UPDATE public.garmondrop_rooms
    SET
      board_state = v_board,
      status = 'completed',
      winner_id = NULL,
      platform_fee_minor = v_fee,
      winner_payout_minor = 0,
      current_turn = NULL,
      move_seq = p_expected_seq + 1,
      completed_at = v_now,
      updated_at = v_now
    WHERE id = p_room_id;

    SELECT * INTO v_room FROM public.garmondrop_rooms WHERE id = p_room_id;
    RETURN jsonb_build_object(
      'success', true,
      'outcome', 'draw',
      'room', row_to_json(v_room)::jsonb
    );
  END IF;

  v_other := CASE WHEN p_user_id = v_room.creator_id THEN v_room.opponent_id ELSE v_room.creator_id END;

  UPDATE public.garmondrop_rooms
  SET
    board_state = v_board,
    current_turn = v_other,
    move_seq = p_expected_seq + 1,
    updated_at = v_now
  WHERE id = p_room_id;

  SELECT * INTO v_room FROM public.garmondrop_rooms WHERE id = p_room_id;
  RETURN jsonb_build_object(
    'success', true,
    'outcome', 'continue',
    'room', row_to_json(v_room)::jsonb
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.garmondrop_post_entry_atomic(p_op text, p_room_id uuid, p_user_id uuid, p_entry_amount integer, p_reference text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_op text := lower(trim(COALESCE(p_op, '')));
  v_now timestamptz := now();
  v_room public.garmondrop_rooms%ROWTYPE;
  v_amt int;
  v_new_id uuid;
BEGIN
  IF p_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'message', 'user_id required');
  END IF;
  IF p_reference IS NULL OR trim(p_reference) = '' THEN
    RETURN jsonb_build_object('success', false, 'message', 'reference required');
  END IF;
  IF EXISTS (SELECT 1 FROM public.coin_transactions WHERE reference = p_reference) THEN
    RETURN jsonb_build_object('success', false, 'message', 'Duplicate transaction');
  END IF;

  v_amt := floor(COALESCE(p_entry_amount, 0));
  IF v_amt < 100 THEN
    RETURN jsonb_build_object('success', false, 'message', 'Entry must be at least 100 GPC');
  END IF;

  IF v_op = 'create' THEN
    IF p_room_id IS NOT NULL THEN
      RETURN jsonb_build_object('success', false, 'message', 'room_id must be null for create');
    END IF;

    UPDATE public.users u
    SET gpay_coins = u.gpay_coins - v_amt
    WHERE u.id = p_user_id AND u.gpay_coins >= v_amt;
    IF NOT FOUND THEN
      RETURN jsonb_build_object('success', false, 'message', 'Insufficient GPay Coins');
    END IF;

    INSERT INTO public.coin_transactions (
      user_id, type, gold_coins, gpay_coins, description, reference
    ) VALUES (
      p_user_id, 'garmondrop_stake', 0, -v_amt,
      'GarmonDrop stake (create room)', p_reference
    );

    INSERT INTO public.garmondrop_rooms (
      creator_id, entry_amount_minor, status, board_state, move_seq, updated_at
    ) VALUES (
      p_user_id, v_amt, 'waiting', public.garmondrop_empty_board(), 0, v_now
    )
    RETURNING id INTO v_new_id;

    RETURN jsonb_build_object('success', true, 'room_id', v_new_id);
  END IF;

  IF v_op = 'join' THEN
    IF p_room_id IS NULL THEN
      RETURN jsonb_build_object('success', false, 'message', 'room_id required to join');
    END IF;

    SELECT * INTO v_room FROM public.garmondrop_rooms WHERE id = p_room_id FOR UPDATE;
    IF NOT FOUND THEN
      RETURN jsonb_build_object('success', false, 'message', 'Room not found');
    END IF;

    IF v_room.status <> 'waiting' OR v_room.opponent_id IS NOT NULL THEN
      RETURN jsonb_build_object('success', false, 'message', 'Room is not open');
    END IF;

    IF v_room.creator_id = p_user_id THEN
      RETURN jsonb_build_object('success', false, 'message', 'Cannot join your own room');
    END IF;

    IF v_room.entry_amount_minor <> v_amt THEN
      RETURN jsonb_build_object('success', false, 'message', 'Entry amount must match room stake');
    END IF;

    UPDATE public.users u
    SET gpay_coins = u.gpay_coins - v_amt
    WHERE u.id = p_user_id AND u.gpay_coins >= v_amt;
    IF NOT FOUND THEN
      RETURN jsonb_build_object('success', false, 'message', 'Insufficient GPay Coins');
    END IF;

    INSERT INTO public.coin_transactions (
      user_id, type, gold_coins, gpay_coins, description, reference
    ) VALUES (
      p_user_id, 'garmondrop_stake', 0, -v_amt,
      'GarmonDrop stake (join room)', p_reference
    );

    UPDATE public.garmondrop_rooms
    SET
      opponent_id = p_user_id,
      status = 'active',
      current_turn = creator_id,
      pot_total_minor = (entry_amount_minor::bigint * 2),
      board_state = public.garmondrop_empty_board(),
      move_seq = 0,
      updated_at = v_now
    WHERE id = p_room_id;

    RETURN jsonb_build_object('success', true, 'room_id', p_room_id);
  END IF;

  RETURN jsonb_build_object('success', false, 'message', 'Invalid op; use create or join');
END;
$function$

CREATE OR REPLACE FUNCTION public.garmondrop_record_platform_fee(p_room_id uuid, p_amount_gpc integer, p_context_user_id uuid, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_amount integer := GREATEST(0, COALESCE(p_amount_gpc, 0));
  v_key text := NULLIF(trim(COALESCE(p_idempotency_key, '')), '');
  v_inserted_id uuid;
BEGIN
  IF v_amount <= 0 THEN
    RETURN jsonb_build_object('inserted', false, 'reason', 'non_positive_amount');
  END IF;
  IF p_room_id IS NULL THEN
    RETURN jsonb_build_object('inserted', false, 'reason', 'room_id_required');
  END IF;
  IF v_key IS NULL THEN
    RETURN jsonb_build_object('inserted', false, 'reason', 'idempotency_key_required');
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.platform_earnings pe WHERE pe.idempotency_key = v_key
  ) THEN
    RETURN jsonb_build_object('inserted', false, 'reason', 'duplicate_or_conflict');
  END IF;

  BEGIN
    INSERT INTO public.platform_earnings (
      source,
      source_id,
      amount_cents,
      description,
      user_id,
      idempotency_key
    )
    VALUES (
      'garmondrop_platform_fee',
      p_room_id::text,
      v_amount,
      'GarmonDrop PvP platform fee (10% of pot)',
      p_context_user_id,
      v_key
    )
    RETURNING id INTO v_inserted_id;
  EXCEPTION
    WHEN unique_violation THEN
      RETURN jsonb_build_object('inserted', false, 'reason', 'duplicate_or_conflict');
  END;

  PERFORM public.platform_record_revenue(v_amount::bigint, 'garmondrop_fee');

  RETURN jsonb_build_object('inserted', true, 'id', v_inserted_id, 'idempotency_key', v_key);
END;
$function$

CREATE OR REPLACE FUNCTION public.garmondrop_repair_turn_atomic(p_room_id uuid, p_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_room public.garmondrop_rooms%ROWTYPE;
  v_now timestamptz := now();
BEGIN
  IF p_room_id IS NULL OR p_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'message', 'room and user required');
  END IF;

  SELECT * INTO v_room FROM public.garmondrop_rooms WHERE id = p_room_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'message', 'Room not found');
  END IF;

  IF p_user_id <> v_room.creator_id AND p_user_id <> v_room.opponent_id THEN
    RETURN jsonb_build_object('success', false, 'message', 'Not a player in this room');
  END IF;

  PERFORM public.garmondrop_fix_null_current_turn(p_room_id, v_now);
  SELECT * INTO v_room FROM public.garmondrop_rooms WHERE id = p_room_id;

  RETURN jsonb_build_object('success', true, 'room', row_to_json(v_room)::jsonb);
END;
$function$

CREATE OR REPLACE FUNCTION public.grant_referral_bonus_for_user(p_referred_user_id uuid, p_bonus_cents bigint DEFAULT 50)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_referred record;
  v_referrer_id uuid;
begin
  if p_bonus_cents is null or p_bonus_cents <= 0 then
    return jsonb_build_object('success', false, 'message', 'Invalid bonus amount');
  end if;
  select id, referred_by_code into v_referred from public.users where id = p_referred_user_id;
  if v_referred is null or v_referred.referred_by_code is null or trim(v_referred.referred_by_code) = '' then
    return jsonb_build_object('success', false, 'message', 'No referrer');
  end if;
  select id into v_referrer_id from public.users where referral_code = v_referred.referred_by_code;
  if v_referrer_id is null then
    return jsonb_build_object('success', false, 'message', 'Referrer not found');
  end if;
  if v_referrer_id = p_referred_user_id then
    return jsonb_build_object('success', false, 'message', 'Cannot self-refer');
  end if;
  -- Prevent duplicate: unique on referred_user_id
  insert into public.referral_bonus (referrer_id, referred_user_id, amount, status)
  values (v_referrer_id, p_referred_user_id, p_bonus_cents, 'paid')
  on conflict (referred_user_id) do nothing;
  if not found then
    return jsonb_build_object('success', false, 'message', 'Bonus already granted');
  end if;
  update public.users set balance = balance + p_bonus_cents, updated_at = now() where id = v_referrer_id;
  insert into public.transactions (user_id, type, amount, status, description, reference_id)
  values (v_referrer_id, 'referral', p_bonus_cents, 'completed', 'Referral bonus', (select id from public.referral_bonus where referred_user_id = p_referred_user_id limit 1));
  insert into public.earnings (user_id, amount, source, reference_id)
  values (v_referrer_id, p_bonus_cents, 'referral', (select id from public.referral_bonus where referred_user_id = p_referred_user_id limit 1));
  insert into public.platform_activities (user_id, activity_type, description, amount_cents)
  values (v_referrer_id, 'referral_bonus', 'Referral bonus earned', p_bonus_cents);
  return jsonb_build_object('success', true, 'referrer_id', v_referrer_id);
end;
$function$

CREATE OR REPLACE FUNCTION public.increment_profile_reportable_earnings(p_user_id uuid, p_delta_cents bigint)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_new bigint;
BEGIN
  IF p_user_id IS NULL THEN
    RETURN 0;
  END IF;
  IF p_delta_cents IS NULL OR p_delta_cents <= 0 THEN
    SELECT COALESCE(reportable_earnings_cents, 0) INTO v_new FROM public.profiles WHERE id = p_user_id;
    RETURN COALESCE(v_new, 0);
  END IF;

  INSERT INTO public.profiles (id, reportable_earnings_cents)
  VALUES (p_user_id, p_delta_cents)
  ON CONFLICT (id) DO UPDATE
    SET reportable_earnings_cents = COALESCE(public.profiles.reportable_earnings_cents, 0) + EXCLUDED.reportable_earnings_cents;

  SELECT reportable_earnings_cents INTO v_new FROM public.profiles WHERE id = p_user_id;
  RETURN COALESCE(v_new, 0);
END;
$function$

CREATE OR REPLACE FUNCTION public.platform_record_payout(p_amount_cents bigint, p_source text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_balance bigint;
  v_rewards bigint;
  v_revenue bigint;
BEGIN
  SELECT balance_cents, total_rewards_paid_cents, total_revenue_cents
  INTO v_balance, v_rewards, v_revenue
  FROM public.platform_balance WHERE id = 'default';
  IF v_balance IS NULL THEN
    RAISE EXCEPTION 'platform_balance row not found';
  END IF;
  IF v_balance < p_amount_cents THEN
    RAISE EXCEPTION 'Insufficient platform balance';
  END IF;
  IF v_rewards + p_amount_cents > v_revenue THEN
    RAISE EXCEPTION 'Payout would exceed total revenue';
  END IF;
  UPDATE public.platform_balance
  SET
    balance_cents = balance_cents - p_amount_cents,
    total_rewards_paid_cents = total_rewards_paid_cents + p_amount_cents,
    updated_at = now()
  WHERE id = 'default';
END;
$function$

CREATE OR REPLACE FUNCTION public.process_subscription_billing(p_subscription_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_sub record;
  v_period_end date;
  v_referrer_id uuid;
  v_referrer_code text;
  v_pct numeric;
  v_commission_cents bigint;
  v_gpc integer;
  v_rc_id uuid;
  v_coin_ref text;
BEGIN
  SELECT * INTO v_sub FROM public.subscriptions WHERE id = p_subscription_id FOR UPDATE;
  IF v_sub IS NULL THEN
    RETURN jsonb_build_object('success', false, 'message', 'Subscription not found');
  END IF;
  IF v_sub.status != 'active' THEN
    RETURN jsonb_build_object('success', false, 'message', 'Subscription not active');
  END IF;

  v_period_end := v_sub.next_billing_date;
  IF v_period_end > CURRENT_DATE THEN
    RETURN jsonb_build_object('success', false, 'message', 'Billing date not yet due');
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.subscription_payments
    WHERE subscription_id = p_subscription_id AND period_end_date = v_period_end
  ) THEN
    RETURN jsonb_build_object('success', false, 'message', 'Already paid for this period');
  END IF;
  INSERT INTO public.subscription_payments (subscription_id, period_end_date)
  VALUES (p_subscription_id, v_period_end);

  SELECT u.referred_by_code INTO v_referrer_code FROM public.users u WHERE u.id = v_sub.user_id;
  IF v_referrer_code IS NULL OR trim(v_referrer_code) = '' THEN
    UPDATE public.subscriptions SET next_billing_date = v_period_end + interval '1 month', updated_at = now() WHERE id = p_subscription_id;
    RETURN jsonb_build_object('success', true, 'commissionPaid', false, 'reason', 'no_referrer');
  END IF;
  SELECT id INTO v_referrer_id FROM public.users WHERE referral_code = v_referrer_code;
  IF v_referrer_id IS NULL OR v_referrer_id = v_sub.user_id THEN
    UPDATE public.subscriptions SET next_billing_date = v_period_end + interval '1 month', updated_at = now() WHERE id = p_subscription_id;
    RETURN jsonb_build_object('success', true, 'commissionPaid', false, 'reason', 'no_referrer');
  END IF;

  SELECT commission_percentage INTO v_pct FROM public.referral_commission_config WHERE membership_tier = v_sub.membership_tier;
  IF v_pct IS NULL THEN
    v_pct := 10;
  END IF;
  v_commission_cents := round(v_sub.monthly_price * v_pct / 100)::bigint;
  IF v_commission_cents <= 0 THEN
    UPDATE public.subscriptions SET next_billing_date = v_period_end + interval '1 month', updated_at = now() WHERE id = p_subscription_id;
    RETURN jsonb_build_object('success', true, 'commissionPaid', false, 'reason', 'zero_commission');
  END IF;

  INSERT INTO public.referral_commissions (referrer_user_id, referred_user_id, subscription_id, commission_amount, last_paid_date, status)
  VALUES (v_referrer_id, v_sub.user_id, p_subscription_id, v_commission_cents, v_period_end, 'active')
  ON CONFLICT (referrer_user_id, referred_user_id, subscription_id) DO UPDATE SET
    commission_amount = excluded.commission_amount,
    last_paid_date = v_period_end,
    updated_at = now()
  WHERE public.referral_commissions.status = 'active';
  SELECT id INTO v_rc_id FROM public.referral_commissions WHERE subscription_id = p_subscription_id AND referrer_user_id = v_referrer_id;

  IF NOT (SELECT (status = 'active') FROM public.referral_commissions WHERE id = v_rc_id) THEN
    UPDATE public.subscriptions SET next_billing_date = v_period_end + interval '1 month', updated_at = now() WHERE id = p_subscription_id;
    RETURN jsonb_build_object('success', true, 'commissionPaid', false, 'reason', 'commission_stopped');
  END IF;

  UPDATE public.referral_commissions SET last_paid_date = v_period_end, updated_at = now() WHERE id = v_rc_id;

  v_gpc := LEAST(v_commission_cents, 2147483647)::integer;
  v_coin_ref := 'referral_comm_rc_' || v_rc_id::text || '_' || v_period_end::text;

  PERFORM public.credit_coins(v_referrer_id, 0, v_gpc);

  INSERT INTO public.coin_transactions (user_id, type, gold_coins, gpay_coins, description, reference)
  VALUES (
    v_referrer_id,
    'referral_commission',
    0,
    v_gpc,
    'Referral commission (recurring)',
    v_coin_ref
  );

  INSERT INTO public.transactions (user_id, type, amount, status, description, reference_id)
  VALUES (v_referrer_id, 'referral_commission', v_gpc, 'completed', 'Referral commission (recurring)', v_rc_id);

  UPDATE public.subscriptions SET next_billing_date = v_period_end + interval '1 month', updated_at = now() WHERE id = p_subscription_id;

  RETURN jsonb_build_object(
    'success', true,
    'commissionPaid', true,
    'commissionGpc', v_gpc,
    'commissionCents', v_gpc,
    'referrerId', v_referrer_id
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.purchase_membership_with_balance_v2(p_user_id uuid, p_tier text, p_price_gc integer, p_extend_from timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_current_gold integer;
  v_period_end timestamptz;
BEGIN
  IF p_tier NOT IN ('starter', 'growth', 'pro', 'elite') THEN
    RAISE EXCEPTION 'Invalid tier: %', p_tier;
  END IF;
  IF p_price_gc <= 0 THEN
    RAISE EXCEPTION 'Price must be positive';
  END IF;

  IF p_extend_from IS NULL THEN
    v_period_end := now() + interval '1 month';
  ELSE
    v_period_end := greatest(now(), p_extend_from) + interval '1 month';
  END IF;

  SELECT gold_coins INTO v_current_gold
  FROM public.users WHERE id = p_user_id FOR UPDATE;

  IF v_current_gold IS NULL THEN
    RAISE EXCEPTION 'User not found';
  END IF;

  IF v_current_gold < p_price_gc THEN
    RAISE EXCEPTION 'Insufficient gold coins (have %, need %)', v_current_gold, p_price_gc;
  END IF;

  UPDATE public.users
  SET gold_coins = gold_coins - p_price_gc,
      membership = p_tier,
      membership_tier = p_tier,
      membership_started_at = COALESCE(membership_started_at, now()),
      membership_period_end = v_period_end,
      membership_expires_at = v_period_end,
      membership_payment_source = 'balance',
      stripe_subscription_id = null,
      subscription_status = 'active',
      updated_at = now()
  WHERE id = p_user_id
  RETURNING membership_period_end INTO v_period_end;

  INSERT INTO public.membership_purchases (user_id, tier, price_gc, payment_method, period_end, created_at)
  VALUES (p_user_id, p_tier, p_price_gc, 'balance', v_period_end, now());

  RETURN jsonb_build_object(
    'success', true,
    'tier', p_tier,
    'price_gc', p_price_gc,
    'remaining_gold', v_current_gold - p_price_gc,
    'period_end', v_period_end
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.request_withdrawal(p_user_id uuid, p_amount_cents bigint, p_method text, p_wallet_address text, p_ip_address text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_withdrawable numeric;
  v_platform_fee numeric;
  v_net_amount numeric;
  v_row public.withdrawals%rowtype;
  v_today_count int;
  v_last_created timestamptz;
  min_cents bigint := 1000;
  max_per_day int := 3;
  cooldown_min interval := interval '5 minutes';
begin
  if p_amount_cents is null or p_amount_cents < min_cents then
    return jsonb_build_object('success', false, 'message', 'Minimum withdrawal is $10.00');
  end if;
  if p_method is null or p_method not in ('crypto', 'paypal', 'bank') then
    return jsonb_build_object('success', false, 'message', 'Invalid method');
  end if;
  if p_wallet_address is null or trim(p_wallet_address) = '' then
    return jsonb_build_object('success', false, 'message', 'Wallet address required');
  end if;

  select withdrawable_balance into v_withdrawable from public.users where id = p_user_id for update;
  if v_withdrawable is null then
    return jsonb_build_object('success', false, 'message', 'User not found');
  end if;
  if v_withdrawable < p_amount_cents then
    return jsonb_build_object('success', false, 'message', 'Insufficient withdrawable balance');
  end if;

  select count(*) into v_today_count
  from public.withdrawals
  where user_id = p_user_id
    and created_at >= date_trunc('day', now())
    and status in ('pending', 'approved', 'paid');
  if v_today_count >= max_per_day then
    return jsonb_build_object('success', false, 'message', 'Maximum 3 withdrawals per day. Try again tomorrow.');
  end if;

  select max(created_at) into v_last_created
  from public.withdrawals
  where user_id = p_user_id and status in ('pending', 'approved', 'paid');
  if v_last_created is not null and (now() - v_last_created) < cooldown_min then
    return jsonb_build_object('success', false, 'message', 'Please wait 5 minutes between withdrawal requests.');
  end if;

  v_platform_fee := round(p_amount_cents * 0.10);
  v_net_amount := p_amount_cents - v_platform_fee;

  update public.users
  set withdrawable_balance = withdrawable_balance - p_amount_cents,
      pending_balance = pending_balance + p_amount_cents,
      updated_at = now()
  where id = p_user_id;

  insert into public.withdrawals (
    user_id, amount, platform_fee, net_amount, status, method, wallet_address, ip_address
  )
  values (
    p_user_id, p_amount_cents, v_platform_fee, v_net_amount, 'pending', p_method,
    trim(p_wallet_address), nullif(trim(coalesce(p_ip_address, '')), '')
  )
  returning * into v_row;

  return jsonb_build_object(
    'success', true,
    'withdrawal', jsonb_build_object(
      'id', v_row.id,
      'amount', v_row.amount,
      'platform_fee', v_row.platform_fee,
      'net_amount', v_row.net_amount,
      'status', v_row.status,
      'method', v_row.method,
      'wallet_address', v_row.wallet_address,
      'created_at', v_row.created_at
    )
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.submit_withdrawal(p_user_id uuid, p_amount bigint, p_method text, p_wallet_address text, p_min_amount bigint DEFAULT 100)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_balance bigint;
  v_row public.withdrawals%rowtype;
begin
  if p_amount is null or p_amount < p_min_amount then
    return jsonb_build_object('success', false, 'message', 'Amount below minimum');
  end if;
  if p_method is null or p_method not in ('crypto', 'paypal', 'bank') then
    return jsonb_build_object('success', false, 'message', 'Invalid method');
  end if;
  if p_wallet_address is null or trim(p_wallet_address) = '' then
    return jsonb_build_object('success', false, 'message', 'Wallet address required');
  end if;

  select balance into v_balance from public.users where id = p_user_id for update;
  if v_balance is null then
    return jsonb_build_object('success', false, 'message', 'User not found');
  end if;
  if v_balance < p_amount then
    return jsonb_build_object('success', false, 'message', 'Insufficient balance');
  end if;

  update public.users set balance = balance - p_amount, updated_at = now() where id = p_user_id;

  insert into public.withdrawals (user_id, amount, status, method, wallet_address)
  values (p_user_id, p_amount, 'pending', p_method, trim(p_wallet_address))
  returning * into v_row;

  insert into public.transactions (user_id, type, amount, status, description, reference_id)
  values (p_user_id, 'withdrawal', p_amount, 'pending', 'Withdrawal request', v_row.id);

  return jsonb_build_object(
    'success', true,
    'withdrawal', jsonb_build_object(
      'id', v_row.id,
      'amount', v_row.amount,
      'status', v_row.status,
      'method', v_row.method,
      'wallet_address', v_row.wallet_address,
      'created_at', v_row.created_at
    )
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.wallet_ledger_entry(p_user_id uuid, p_type text, p_amount_cents bigint, p_reference text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_current bigint;
  v_balance_after bigint;
  v_ledger_id uuid;
  v_valid_types text[] := array[
    'deposit','withdrawal','game_play','game_win','referral_bonus',
    'subscription_payment','commission_payout','admin_adjustment','ad_earning'
  ];
BEGIN
  IF p_type IS NULL OR NOT (p_type = ANY(v_valid_types)) THEN
    RETURN jsonb_build_object('success', false, 'message', 'Invalid type');
  END IF;
  IF p_amount_cents = 0 THEN
    RETURN jsonb_build_object('success', false, 'message', 'Amount cannot be zero');
  END IF;
  IF p_reference IS NOT NULL AND trim(p_reference) != '' THEN
    IF EXISTS (SELECT 1 FROM public.wallet_ledger WHERE reference = p_reference) THEN
      RETURN jsonb_build_object('success', false, 'message', 'Duplicate transaction');
    END IF;
  END IF;

  INSERT INTO public.wallet_balances (user_id, balance, updated_at)
  VALUES (p_user_id, 0, now())
  ON CONFLICT (user_id) DO NOTHING;

  SELECT balance INTO v_current
  FROM public.wallet_balances
  WHERE user_id = p_user_id
  FOR UPDATE;

  IF v_current IS NULL THEN
    RETURN jsonb_build_object('success', false, 'message', 'User balance row not found');
  END IF;

  v_balance_after := v_current + p_amount_cents;

  IF v_balance_after < 0 THEN
    RETURN jsonb_build_object('success', false, 'message', 'Insufficient balance');
  END IF;

  INSERT INTO public.wallet_ledger (user_id, type, amount, balance_after, reference)
  VALUES (p_user_id, p_type, p_amount_cents, v_balance_after, nullif(trim(p_reference), ''))
  RETURNING id INTO v_ledger_id;

  UPDATE public.wallet_balances
  SET balance = v_balance_after, updated_at = now()
  WHERE user_id = p_user_id;

  RETURN jsonb_build_object(
    'success', true,
    'balance_cents', v_balance_after,
    'ledger_id', v_ledger_id
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.celo_wallet_move(p_user uuid, p_amount integer, p_reference text, p_type text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_result jsonb;
BEGIN
 IF p_amount=0 THEN RETURN; END IF;
 IF EXISTS(SELECT 1 FROM coin_transactions WHERE reference=p_reference) THEN RAISE EXCEPTION 'Duplicate C-Lo ledger reference'; END IF;
 IF p_amount<0 THEN
  UPDATE users SET gpay_coins=gpay_coins+p_amount WHERE id=p_user AND gpay_coins>=-p_amount;
  IF NOT FOUND THEN RAISE EXCEPTION 'Insufficient GPC balance'; END IF;
  INSERT INTO coin_transactions(user_id,type,gold_coins,gpay_coins,description,reference) VALUES(p_user,p_type,0,p_amount,'C-Lo escrow transfer',p_reference);
 ELSE
  v_result:=credit_coins_with_ledger(p_user,0,p_amount,p_type,'C-Lo escrow transfer',p_reference);
  IF (v_result->>'success') IS DISTINCT FROM 'true' THEN RAISE EXCEPTION '%',COALESCE(v_result->>'message','C-Lo credit failed'); END IF;
 END IF;
END $function$

CREATE OR REPLACE FUNCTION public.celo_room_action_atomic(p_user uuid, p_room uuid, p_action text, p_request uuid, p_input jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE r celo_rooms%ROWTYPE; a celo_rounds%ROWTYPE; p celo_room_players%ROWTYPE;
 v_receipt celo_action_receipts%ROWTYPE; v_hash text; v_response jsonb; v_amount integer; v_min integer; v_seat integer; v_count integer; v_prize integer; v_round integer; v_name text; v_role text;
BEGIN
 IF p_user IS NULL OR p_request IS NULL THEN RAISE EXCEPTION 'Authenticated user and request id required'; END IF;
 -- Serialize request retries. Game actions use table -> round -> wallet lock order.
 PERFORM pg_advisory_xact_lock(hashtextextended(p_request::text,0));
 PERFORM 1 FROM users WHERE id=p_user;
 IF NOT FOUND THEN RAISE EXCEPTION 'User not found'; END IF;
 v_hash:=md5(COALESCE(p_room::text,'')||p_action||p_input::text);
 SELECT * INTO v_receipt FROM celo_action_receipts WHERE request_id=p_request;
 IF FOUND THEN
  IF v_receipt.user_id<>p_user OR v_receipt.action<>p_action OR v_receipt.input_hash<>v_hash THEN RAISE EXCEPTION 'Request id belongs to a different action'; END IF;
  RETURN v_receipt.response || jsonb_build_object('idempotent',true);
 END IF;
 IF p_action='create' THEN
  v_min:=(p_input->>'minimum_entry_sc')::integer;v_amount:=(p_input->>'starting_bank_sc')::integer;v_name:=trim(p_input->>'name');v_count:=(p_input->>'max_players')::integer;
  IF v_min IS NULL OR v_min<500 OR v_amount IS NULL OR v_amount<v_min OR v_amount%v_min<>0 OR v_count IS NULL OR v_count NOT IN(2,4,6,10) OR COALESCE(v_name,'')='' THEN RAISE EXCEPTION 'Invalid room settings'; END IF;
  PERFORM celo_wallet_move(p_user,-v_amount,'celo:create:'||p_request,'celo_entry');
  INSERT INTO celo_rooms(name,creator_id,banker_id,status,room_type,max_players,min_bet_cents,max_bet_cents,minimum_entry_sc,current_bank_sc,current_bank_cents,platform_fee_pct,last_activity)
  VALUES(v_name,p_user,p_user,'waiting','public',v_count,v_min,GREATEST(10000,v_amount*4),v_min,v_amount,v_amount,10,now()) RETURNING * INTO r;
  INSERT INTO celo_room_players(room_id,user_id,role,seat_number,entry_sc,bet_cents,dice_type) VALUES(r.id,p_user,'banker',0,0,0,'standard') RETURNING * INTO p;
 ELSE
  SELECT * INTO r FROM celo_rooms WHERE id=p_room FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Room not found'; END IF;
  SELECT * INTO a FROM celo_rounds WHERE room_id=r.id AND status IN('banker_rolling','player_rolling','betting') ORDER BY round_number DESC LIMIT 1 FOR UPDATE;
  SELECT * INTO p FROM celo_room_players WHERE room_id=r.id AND user_id=p_user;
  IF p_action='join' AND p.id IS NOT NULL THEN
   v_response:=jsonb_build_object('ok',true,'room',to_jsonb(r),'player',to_jsonb(p),'already_seated',true);
  ELSE
   IF r.status IN('cancelled','closed','completed') THEN RAISE EXCEPTION 'Room is closed'; END IF;
   IF p_action NOT IN('resume','leave','delete') AND r.paused_at IS NOT NULL THEN RAISE EXCEPTION 'Room is paused'; END IF;
   IF a.id IS NOT NULL THEN
    IF p_action='start' AND r.banker_id=p_user THEN v_response:=jsonb_build_object('ok',true,'room',to_jsonb(r),'round',to_jsonb(a),'idempotent',true);
    ELSE RAISE EXCEPTION 'A round is already in progress'; END IF;
   ELSIF p_action='join' THEN
    v_role:=COALESCE(p_input->>'role','player');IF v_role NOT IN('player','spectator') THEN RAISE EXCEPTION 'Invalid role'; END IF;
    SELECT count(*) INTO v_count FROM celo_room_players WHERE room_id=r.id;
    IF v_count>=r.max_players THEN RAISE EXCEPTION 'Table is full'; END IF;
    SELECT s INTO v_seat FROM generate_series(1,r.max_players-1) s WHERE NOT EXISTS(SELECT 1 FROM celo_room_players WHERE room_id=r.id AND seat_number=s) ORDER BY s LIMIT 1;
    IF v_seat IS NULL THEN RAISE EXCEPTION 'Table is full'; END IF;
    INSERT INTO celo_room_players(room_id,user_id,role,seat_number,entry_sc,bet_cents,dice_type) VALUES(r.id,p_user,v_role,v_seat,0,0,'standard') RETURNING * INTO p;
   ELSIF p_action='entry' THEN
    v_amount:=(p_input->>'amount')::integer;v_min:=GREATEST(500,COALESCE(r.minimum_entry_sc,r.min_bet_cents,500));
    IF p.id IS NULL OR p.role<>'player' OR r.banker_id=p_user THEN RAISE EXCEPTION 'Only a seated player may post entry'; END IF;
    IF v_amount IS NULL OR v_amount<v_min OR v_amount>r.current_bank_sc THEN RAISE EXCEPTION 'Entry must be between the minimum and current bank'; END IF;
    IF p.entry_posted OR GREATEST(p.entry_sc,p.stake_amount_sc,p.bet_cents)>0 THEN RAISE EXCEPTION 'Entry already posted'; END IF;
    SELECT COALESCE(sum(GREATEST(entry_sc,stake_amount_sc,bet_cents)),0) INTO v_prize FROM celo_room_players WHERE room_id=r.id AND role='player' AND entry_posted;
    IF v_prize+v_amount>r.current_bank_sc THEN RAISE EXCEPTION 'Remaining bank coverage is insufficient for this entry'; END IF;
    PERFORM celo_wallet_move(p_user,-v_amount,'celo:entry:'||p_request,'celo_entry');
    UPDATE celo_room_players SET entry_sc=v_amount,stake_amount_sc=v_amount,bet_cents=v_amount,entry_posted=true,status='active',player_seat_status='active' WHERE id=p.id RETURNING * INTO p;
    UPDATE celo_rooms SET status='active',last_activity=now() WHERE id=r.id RETURNING * INTO r;
   ELSIF p_action='start' THEN
    IF r.banker_id IS DISTINCT FROM p_user THEN RAISE EXCEPTION 'Only the banker can start a round'; END IF;
    IF r.current_bank_sc<=0 OR r.bank_busted THEN RAISE EXCEPTION 'Fund the bank before starting'; END IF;
    SELECT COALESCE(sum(GREATEST(entry_sc,stake_amount_sc,bet_cents)),0),count(*) INTO v_prize,v_count FROM celo_room_players WHERE room_id=r.id AND role='player' AND user_id<>r.banker_id AND entry_posted AND GREATEST(entry_sc,stake_amount_sc,bet_cents)>0;
    IF v_count<1 THEN RAISE EXCEPTION 'At least one posted entry is required'; END IF;
    IF v_prize>r.current_bank_sc THEN RAISE EXCEPTION 'Entries exceed bank coverage'; END IF;
    SELECT COALESCE(max(round_number),0)+1 INTO v_round FROM celo_rounds WHERE room_id=r.id;
    INSERT INTO celo_rounds(room_id,round_number,banker_id,status,prize_pool_sc,platform_fee_sc,bank_covered,bank_at_round_start_sc,settlement_version)
    VALUES(r.id,v_round,p_user,'banker_rolling',v_prize,0,false,r.current_bank_sc,2) RETURNING * INTO a;
    UPDATE celo_rounds SET entry_snapshot=(SELECT jsonb_agg(jsonb_build_object('user_id',user_id,'stake_sc',stake_amount_sc,'seat',seat_number) ORDER BY seat_number) FROM celo_room_players WHERE room_id=r.id AND role='player' AND entry_posted) WHERE id=a.id RETURNING * INTO a;
    UPDATE celo_rooms SET status='rolling',last_activity=now() WHERE id=r.id RETURNING * INTO r;
   ELSIF p_action='fund' THEN
    IF r.banker_id IS DISTINCT FROM p_user THEN RAISE EXCEPTION 'Only the banker can fund the bank'; END IF;
    v_amount:=(p_input->>'amount')::integer;v_min:=GREATEST(500,COALESCE(r.minimum_entry_sc,r.min_bet_cents,500));
    IF v_amount IS NULL OR v_amount<v_min OR v_amount%v_min<>0 THEN RAISE EXCEPTION 'Invalid bank funding amount'; END IF;
    PERFORM celo_wallet_move(p_user,-v_amount,'celo:fund:'||p_request,'celo_entry');
    UPDATE celo_rooms SET current_bank_sc=current_bank_sc+v_amount,current_bank_cents=current_bank_sc+v_amount,bank_busted=false,status='waiting',last_activity=now() WHERE id=r.id RETURNING * INTO r;
   ELSIF p_action='vote' THEN
    IF p.id IS NULL OR p.role<>'player' OR r.banker_id=p_user THEN RAISE EXCEPTION 'Only a seated player may vote'; END IF;
    v_role:=p_input->>'vote';IF v_role NOT IN('request','approve') THEN RAISE EXCEPTION 'Invalid pause vote'; END IF;
    INSERT INTO celo_pause_votes(room_id,user_id,vote) VALUES(r.id,p_user,v_role) ON CONFLICT(room_id,user_id,vote) DO NOTHING;
    SELECT count(*) INTO v_count FROM celo_room_players WHERE room_id=r.id AND role='player' AND user_id<>r.banker_id AND seat_number IS NOT NULL;
    SELECT count(*) INTO v_prize FROM celo_pause_votes v JOIN celo_room_players p ON p.room_id=v.room_id AND p.user_id=v.user_id WHERE v.room_id=r.id AND v.vote='approve' AND p.role='player';
    IF v_role='approve' AND v_count>0 AND v_prize>=floor(v_count/2.0)+1 THEN UPDATE celo_rooms SET paused_at=now(),paused_by=p_user,pause_reason='majority_player_vote',pause_expires_at=now()+interval '5 minutes',last_activity=now() WHERE id=r.id RETURNING * INTO r; END IF;
   ELSIF p_action='reset-votes' THEN
    IF r.banker_id IS DISTINCT FROM p_user THEN RAISE EXCEPTION 'Only the banker may reject pause requests';END IF;
    DELETE FROM celo_pause_votes WHERE room_id=r.id;
   ELSIF p_action='rules' THEN
    IF r.banker_id IS DISTINCT FROM p_user THEN RAISE EXCEPTION 'Only the banker may edit room settings'; END IF;
    IF r.current_bank_sc>0 OR EXISTS(SELECT 1 FROM celo_room_players WHERE room_id=r.id AND entry_posted) THEN RAISE EXCEPTION 'Room settings require an unfunded bank without entries'; END IF;
    v_min:=(p_input->>'minimum_entry_sc')::integer;v_name:=trim(p_input->>'name');v_count:=(p_input->>'max_players')::integer;
    IF v_min IS NULL OR v_min<500 OR v_count IS NULL OR v_count NOT IN(2,4,6,10) OR COALESCE(v_name,'')='' OR length(v_name)>40 OR v_count<(SELECT count(*) FROM celo_room_players WHERE room_id=r.id) THEN RAISE EXCEPTION 'Invalid room settings'; END IF;
    UPDATE celo_rooms SET name=v_name,minimum_entry_sc=v_min,min_bet_cents=v_min,max_players=v_count,last_activity=now() WHERE id=r.id RETURNING * INTO r;
   ELSIF p_action='takeover' THEN
    SELECT * INTO a FROM celo_rounds WHERE id=(p_input->>'round_id')::uuid AND room_id=r.id FOR UPDATE;
    IF a.id IS NULL OR NOT a.player_celo_offer OR a.player_celo_expires_at<now() THEN RAISE EXCEPTION 'No current C-Lo banker offer'; END IF;
    IF p.id IS NULL OR NOT EXISTS(SELECT 1 FROM celo_player_rolls WHERE round_id=a.id AND user_id=p_user AND outcome='win' AND (SELECT array_agg(d ORDER BY d) FROM unnest(dice) d)=ARRAY[4,5,6]) THEN RAISE EXCEPTION 'Only the winning C-Lo roller may accept'; END IF;
    IF COALESCE((p_input->>'accept')::boolean,false) THEN
     IF a.status<>'completed' OR EXISTS(SELECT 1 FROM celo_room_players WHERE room_id=r.id AND entry_posted) THEN RAISE EXCEPTION 'Finish current entries before takeover'; END IF;
     IF r.banker_id=p_user THEN RAISE EXCEPTION 'Already the banker'; END IF;
     -- Swap occupied seats through NULL so the unique room/seat index remains valid.
     UPDATE celo_room_players SET seat_number=NULL WHERE room_id=r.id AND user_id IN(r.banker_id,p_user);
     UPDATE celo_room_players SET seat_number=p.seat_number,role='player' WHERE room_id=r.id AND user_id=r.banker_id;
     UPDATE celo_room_players SET seat_number=0,role='banker' WHERE id=p.id RETURNING * INTO p;
     UPDATE celo_rooms SET banker_id=p_user,bank_busted=(current_bank_sc<=0),last_activity=now() WHERE id=r.id RETURNING * INTO r;
    END IF;
    UPDATE celo_rounds SET player_celo_offer=false,player_celo_expires_at=NULL WHERE id=a.id RETURNING * INTO a;
   ELSIF p_action='setup' THEN
    IF r.banker_id IS DISTINCT FROM p_user THEN RAISE EXCEPTION 'Only the banker can set up the bank'; END IF;
    IF r.current_bank_sc>0 THEN RAISE EXCEPTION 'Bank is already funded'; END IF;
    v_min:=(p_input->>'minimum_entry_sc')::integer;v_amount:=(p_input->>'funding_amount_sc')::integer;v_name:=trim(p_input->>'name');v_count:=(p_input->>'max_players')::integer;
    IF v_min IS NULL OR v_min<500 OR v_amount IS NULL OR v_amount<v_min OR v_amount%v_min<>0 OR v_count IS NULL OR v_count NOT IN(2,4,6,10) OR COALESCE(v_name,'')='' THEN RAISE EXCEPTION 'Invalid room settings'; END IF;
    IF EXISTS(SELECT 1 FROM celo_room_players WHERE room_id=r.id AND entry_posted) THEN RAISE EXCEPTION 'Posted entries must finish before setup'; END IF;
    PERFORM celo_wallet_move(p_user,-v_amount,'celo:setup:'||p_request,'celo_entry');
    UPDATE celo_rooms SET name=v_name,minimum_entry_sc=v_min,min_bet_cents=v_min,max_players=v_count,current_bank_sc=v_amount,current_bank_cents=v_amount,bank_busted=false,status='waiting',last_activity=now() WHERE id=r.id RETURNING * INTO r;
   ELSIF p_action='lower' THEN
    IF r.banker_id IS DISTINCT FROM p_user THEN RAISE EXCEPTION 'Only the banker can lower the bank'; END IF;
    IF NOT r.last_round_was_celo OR r.banker_celo_at IS NULL OR r.banker_celo_at<now()-interval '60 seconds' THEN RAISE EXCEPTION 'Lower bank is only available within one minute of C-Lo'; END IF;
    v_amount:=(p_input->>'new_bank_sc')::integer;v_min:=GREATEST(500,COALESCE(r.minimum_entry_sc,r.min_bet_cents,500));
    IF v_amount IS NULL OR v_amount<v_min OR v_amount>=r.current_bank_sc OR v_amount%v_min<>0 THEN RAISE EXCEPTION 'Invalid lower bank amount'; END IF;
    SELECT COALESCE(sum(stake_amount_sc),0) INTO v_prize FROM celo_room_players WHERE room_id=r.id AND entry_posted;
    IF v_amount<v_prize THEN RAISE EXCEPTION 'Posted entries exceed new bank coverage'; END IF;
    PERFORM celo_wallet_move(p_user,r.current_bank_sc-v_amount,'celo:lower:'||p_request,'celo_bank_refund');
    UPDATE celo_rooms SET current_bank_sc=v_amount,current_bank_cents=v_amount,last_round_was_celo=false,last_activity=now() WHERE id=r.id RETURNING * INTO r;
   ELSIF p_action='pause' OR p_action='resume' THEN
    IF r.banker_id IS DISTINCT FROM p_user THEN RAISE EXCEPTION 'Only the banker may pause or resume'; END IF;
    UPDATE celo_rooms SET paused_at=CASE WHEN p_action='pause' THEN now() ELSE NULL END,paused_by=CASE WHEN p_action='pause' THEN p_user ELSE NULL END,pause_expires_at=CASE WHEN p_action='pause' THEN now()+interval '5 minutes' ELSE NULL END,last_activity=now() WHERE id=r.id RETURNING * INTO r;
    DELETE FROM celo_pause_votes WHERE room_id=r.id;
   ELSIF p_action='leave' THEN
    IF p.id IS NULL THEN RAISE EXCEPTION 'Not seated'; END IF;
    IF r.banker_id=p_user THEN RAISE EXCEPTION 'Banker must close the table before leaving'; END IF;
    IF p.entry_posted AND p.stake_amount_sc>0 THEN PERFORM celo_wallet_move(p_user,p.stake_amount_sc,'celo:leave:'||p_request,'celo_bank_refund'); END IF;
    DELETE FROM celo_room_players WHERE id=p.id;p:=NULL;
   ELSIF p_action='delete' THEN
    IF r.banker_id IS DISTINCT FROM p_user THEN RAISE EXCEPTION 'Only the banker can close the table'; END IF;
    IF EXISTS(SELECT 1 FROM celo_room_players WHERE room_id=r.id AND entry_posted AND stake_amount_sc>0) THEN RAISE EXCEPTION 'Posted entries must finish before closing'; END IF;
    IF EXISTS(SELECT 1 FROM celo_side_bets WHERE room_id=r.id AND status IN('open','matched')) THEN RAISE EXCEPTION 'Side bets must finish before closing'; END IF;
    PERFORM celo_wallet_move(p_user,r.current_bank_sc,'celo:close:'||p_request,'celo_bank_refund');
    UPDATE celo_rooms SET status='cancelled',current_bank_sc=0,current_bank_cents=0,last_activity=now() WHERE id=r.id RETURNING * INTO r;
    DELETE FROM celo_room_players WHERE room_id=r.id;
   ELSE RAISE EXCEPTION 'Unknown C-Lo action'; END IF;
  END IF;
 END IF;
 v_response:=COALESCE(v_response,jsonb_build_object('ok',true,'room',to_jsonb(r),'player',to_jsonb(p),'round',to_jsonb(a)));
 INSERT INTO celo_action_receipts(request_id,user_id,room_id,action,input_hash,response) VALUES(p_request,p_user,r.id,p_action,v_hash,v_response);
 RETURN v_response;
END $function$

CREATE OR REPLACE FUNCTION public.celo_claim_roll_atomic(p_user uuid, p_room uuid, p_round uuid, p_request uuid, p_seq integer, p_timeout boolean DEFAULT false, p_payload jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE r celo_rooms%ROWTYPE;a celo_rounds%ROWTYPE;p celo_room_players%ROWTYPE; v_saved jsonb;
BEGIN
 SELECT * INTO r FROM celo_rooms WHERE id=p_room FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Room not found'; END IF;
 SELECT * INTO a FROM celo_rounds WHERE id=p_round AND room_id=p_room FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Round not found'; END IF;
 IF r.status='cancelled' THEN RAISE EXCEPTION 'Room is closed'; END IF;
 IF r.paused_at IS NOT NULL THEN RAISE EXCEPTION 'Room is paused'; END IF;
 SELECT response INTO v_saved FROM celo_action_receipts WHERE request_id=p_request AND user_id=p_user AND action='roll';
 IF FOUND THEN RETURN jsonb_build_object('replay',v_saved); END IF;
 IF a.status NOT IN('banker_rolling','player_rolling') THEN RAISE EXCEPTION 'No active round'; END IF;
 SELECT * INTO p FROM celo_room_players WHERE room_id=p_room AND user_id=p_user;
 IF p.id IS NULL THEN RAISE EXCEPTION 'Not seated'; END IF;
 IF p_timeout THEN
  IF a.pending_roll_payload->'dice' IS NOT NULL AND a.pending_roll_payload->'dice'<>'null'::jsonb THEN RAISE EXCEPTION 'Accepted player roll must settle before timeout'; END IF;
  IF a.status<>'player_rolling' OR a.player_roll_deadline_at IS NULL OR a.player_roll_deadline_at>now() THEN RAISE EXCEPTION 'Player deadline has not expired'; END IF;
 ELSE
  IF p_seq IS NULL OR p_seq<>a.roll_seq THEN RAISE EXCEPTION 'Stale roll version; synchronize table'; END IF;
  IF a.status='banker_rolling' THEN
   IF r.banker_id IS DISTINCT FROM p_user THEN RAISE EXCEPTION 'Only the banker may roll now'; END IF;
  ELSIF p.user_id IS DISTINCT FROM a.roller_user_id OR p.role<>'player' OR NOT p.entry_posted OR p.stake_amount_sc<=0 THEN RAISE EXCEPTION 'Not your turn'; END IF;
 END IF;
 IF a.pending_roll_id=p_request THEN RETURN jsonb_build_object('round',to_jsonb(a),'room',to_jsonb(r),'payload',a.pending_roll_payload); END IF;
 IF a.pending_roll_id IS NOT NULL AND a.roll_animation_start_at>now()-interval '30 seconds' THEN RAISE EXCEPTION 'Roll already in progress'; END IF;
 UPDATE celo_rooms SET last_activity=now() WHERE id=r.id;
 UPDATE celo_rounds SET pending_roll_id=p_request,pending_roll_user_id=p_user,pending_roll_payload=COALESCE(pending_roll_payload,p_payload),banker_roll_in_flight=(status='banker_rolling'),roll_processing=(status='player_rolling'),roll_animation_start_at=now(),roll_animation_duration_ms=1500 WHERE id=a.id RETURNING * INTO a;
 RETURN jsonb_build_object('round',to_jsonb(a),'room',to_jsonb(r),'payload',a.pending_roll_payload);
END $function$

CREATE OR REPLACE FUNCTION public.celo_settle_roll_atomic(p_user uuid, p_room uuid, p_round uuid, p_request uuid, p_dice integer[], p_result text, p_name text, p_point integer, p_is_celo boolean, p_timeout boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE r celo_rooms%ROWTYPE;a celo_rounds%ROWTYPE;p celo_room_players%ROWTYPE;s celo_room_players%ROWTYPE;
 v_outcome text;v_entry integer;v_fee integer;v_net integer;v_payout integer:=0;v_total_fee integer:=0;v_delta integer:=0;v_winner uuid;v_best integer:=-1;v_next celo_room_players%ROWTYPE;v_receipt jsonb;v_complete boolean:=false;v_roll celo_player_rolls%ROWTYPE;v_old_banker uuid;v_response jsonb;v_target uuid;v_winners jsonb:='[]'::jsonb;
BEGIN
 SELECT * INTO r FROM celo_rooms WHERE id=p_room FOR UPDATE;
 SELECT * INTO a FROM celo_rounds WHERE id=p_round AND room_id=p_room FOR UPDATE;
 SELECT response INTO v_receipt FROM celo_action_receipts WHERE request_id=p_request AND user_id=p_user AND action='roll';
 IF FOUND THEN RETURN v_receipt||jsonb_build_object('idempotent',true); END IF;
 IF a.id IS NULL OR a.pending_roll_id IS DISTINCT FROM p_request OR a.status NOT IN('banker_rolling','player_rolling') THEN RAISE EXCEPTION 'Roll claim is no longer valid'; END IF;
 IF p_result NOT IN('instant_win','instant_loss','point','no_count') OR (NOT p_timeout AND (array_length(p_dice,1)<>3 OR EXISTS(SELECT 1 FROM unnest(p_dice) d WHERE d NOT BETWEEN 1 AND 6))) THEN RAISE EXCEPTION 'Invalid trusted roll'; END IF;
 IF a.pending_roll_payload IS NOT NULL AND (a.pending_roll_payload->'dice' IS DISTINCT FROM COALESCE(to_jsonb(p_dice),'null'::jsonb) OR a.pending_roll_payload->>'result' IS DISTINCT FROM p_result OR a.pending_roll_payload->>'rollName' IS DISTINCT FROM p_name OR (a.pending_roll_payload->>'point')::integer IS DISTINCT FROM p_point OR (a.pending_roll_payload->>'isCelo')::boolean IS DISTINCT FROM p_is_celo) THEN RAISE EXCEPTION 'Settlement differs from accepted server roll'; END IF;
 -- Lock affected wallets in UUID order across tables to avoid opposite-player deadlocks.
 PERFORM 1 FROM users WHERE id IN(SELECT user_id FROM celo_room_players WHERE room_id=r.id UNION SELECT creator_id FROM celo_side_bets WHERE room_id=r.id AND status IN('open','matched') UNION SELECT acceptor_id FROM celo_side_bets WHERE room_id=r.id AND status='matched') ORDER BY id FOR UPDATE;
 v_old_banker:=r.banker_id;v_target:=CASE WHEN p_timeout THEN a.roller_user_id ELSE p_user END;
 SELECT * INTO p FROM celo_room_players WHERE room_id=r.id AND user_id=v_target;
 IF a.status='banker_rolling' THEN
  IF r.banker_id IS DISTINCT FROM p_user THEN RAISE EXCEPTION 'Banker identity changed'; END IF;
  UPDATE celo_rounds SET banker_dice=p_dice,banker_dice_name=p_name,banker_dice_result=p_result,banker_point=p_point,banker_rerolls=banker_rerolls+CASE WHEN p_result='no_count' THEN 1 ELSE 0 END WHERE id=a.id;
  IF p_result IN('instant_win','instant_loss') THEN
   FOR s IN SELECT * FROM celo_room_players WHERE room_id=r.id AND role='player' AND entry_posted AND stake_amount_sc>0 ORDER BY seat_number,user_id FOR UPDATE LOOP
    v_entry:=s.stake_amount_sc;v_fee:=floor(v_entry*.1);v_net:=v_entry-v_fee;v_total_fee:=v_total_fee+v_fee;
    IF p_result='instant_win' THEN v_delta:=v_delta+v_net;
    ELSE
     PERFORM celo_wallet_move(s.user_id,v_entry+v_net,'celo:roll:'||p_request||':'||s.user_id,'celo_payout');
     v_winners:=v_winners||jsonb_build_array(jsonb_build_object('user_id',s.user_id,'payout_sc',v_entry+v_net));
     v_delta:=v_delta-CASE WHEN a.settlement_version>=2 THEN v_entry ELSE v_net END;
     IF v_entry>v_best THEN v_best:=v_entry;v_winner:=s.user_id; END IF;
    END IF;
   END LOOP;
   v_outcome:=CASE WHEN p_result='instant_win' THEN 'banker_win' ELSE 'players_win' END;v_complete:=true;
   UPDATE celo_rounds SET banker_winnings_sc=CASE WHEN p_result='instant_win' THEN v_delta ELSE v_delta+v_total_fee END,platform_fee_sc=v_total_fee WHERE id=a.id;
  ELSIF p_result='point' THEN
   SELECT * INTO v_next FROM celo_room_players WHERE room_id=r.id AND role='player' AND entry_posted AND stake_amount_sc>0 ORDER BY seat_number,user_id LIMIT 1;
   IF v_next.id IS NULL THEN RAISE EXCEPTION 'No funded player for banker point'; END IF;
   UPDATE celo_rounds SET status='player_rolling',current_player_seat=v_next.seat_number,roller_user_id=v_next.user_id,player_roll_deadline_at=now()+interval '30 seconds' WHERE id=a.id;
   v_outcome:='point';
  ELSE v_outcome:='reroll'; END IF;
 ELSE
  IF p.id IS NULL OR p.user_id IS DISTINCT FROM a.roller_user_id OR p.stake_amount_sc<=0 OR NOT p.entry_posted THEN RAISE EXCEPTION 'Player state changed'; END IF;
  v_entry:=p.stake_amount_sc;v_fee:=floor(v_entry*.1);v_net:=v_entry-v_fee;
  v_outcome:=CASE WHEN p_timeout THEN 'loss' WHEN p_result='no_count' THEN 'reroll' WHEN p_result='instant_win' THEN 'win' WHEN p_result='instant_loss' THEN 'loss' WHEN p_point=a.banker_point THEN 'push' WHEN p_point>a.banker_point THEN 'win' ELSE 'loss' END;
  IF v_outcome='push' THEN
   FOR s IN SELECT * FROM celo_room_players WHERE room_id=r.id AND role='player' AND entry_posted AND stake_amount_sc>0 ORDER BY seat_number,user_id FOR UPDATE LOOP
    PERFORM celo_wallet_move(s.user_id,s.stake_amount_sc,'celo:push:'||p_request||':'||s.user_id,'celo_payout');
   END LOOP;
   v_payout:=v_entry;v_fee:=0;v_complete:=true;
   UPDATE celo_rounds SET push=true WHERE id=a.id;
  ELSIF v_outcome='win' THEN
   v_payout:=v_entry+v_net;PERFORM celo_wallet_move(p.user_id,v_payout,'celo:roll:'||p_request||':'||p.user_id,'celo_payout');
   v_delta:=-CASE WHEN a.settlement_version>=2 THEN v_entry ELSE v_net END;v_winner:=p.user_id;
   UPDATE celo_rounds SET banker_winnings_sc=banker_winnings_sc-v_net,platform_fee_sc=platform_fee_sc+v_fee,player_celo_offer=player_celo_offer OR p_is_celo,player_celo_expires_at=CASE WHEN p_is_celo THEN now()+interval '30 seconds' ELSE player_celo_expires_at END WHERE id=a.id;
  ELSIF v_outcome='loss' THEN
   v_delta:=v_net;UPDATE celo_rounds SET banker_winnings_sc=banker_winnings_sc+v_net,platform_fee_sc=platform_fee_sc+v_fee WHERE id=a.id;
  END IF;
  INSERT INTO celo_player_rolls(round_id,room_id,user_id,dice,roll_name,roll_result,point,entry_sc,outcome,payout_sc,platform_fee_sc)
  VALUES(a.id,r.id,p.user_id,COALESCE(p_dice,ARRAY[]::integer[]),p_name,p_result,p_point,v_entry,v_outcome,v_payout,CASE WHEN v_outcome IN('win','loss') THEN v_fee ELSE 0 END) RETURNING * INTO v_roll;
  IF v_outcome<>'reroll' THEN
   UPDATE celo_room_players SET entry_sc=0,bet_cents=0,stake_amount_sc=0,entry_posted=false,status='seated',player_seat_status='seated' WHERE id=p.id;
   SELECT * INTO v_next FROM celo_room_players WHERE room_id=r.id AND role='player' AND entry_posted AND stake_amount_sc>0 ORDER BY seat_number,user_id LIMIT 1;
   IF v_next.id IS NULL THEN v_complete:=true;
   ELSIF NOT v_complete THEN UPDATE celo_rounds SET current_player_seat=v_next.seat_number,roller_user_id=v_next.user_id,player_roll_deadline_at=now()+interval '30 seconds' WHERE id=a.id; END IF;
  END IF;
 END IF;
 IF r.current_bank_sc+v_delta<0 THEN RAISE EXCEPTION 'Insufficient table escrow for settlement'; END IF;
 UPDATE celo_rooms SET current_bank_sc=current_bank_sc+v_delta,current_bank_cents=current_bank_sc+v_delta,last_activity=now() WHERE id=r.id RETURNING * INTO r;
 IF r.current_bank_sc=0 AND v_winner IS NOT NULL THEN
  PERFORM celo_handle_bank_bust_and_transfer(r.id,v_winner,0,'atomic_roll');
  SELECT * INTO r FROM celo_rooms WHERE id=r.id;
 END IF;
 IF v_complete THEN
  UPDATE celo_rounds SET status='completed',completed_at=now(),player_celo_offer=player_celo_offer AND r.current_bank_sc>0,player_celo_expires_at=CASE WHEN player_celo_offer AND r.current_bank_sc>0 THEN now()+interval '30 seconds' ELSE NULL END,player_roll_deadline_at=NULL,terminal_room_bank_applied=true,terminal_bank_delta_sc=v_delta WHERE id=a.id;
  UPDATE celo_room_players SET entry_sc=0,bet_cents=0,stake_amount_sc=0,entry_posted=false,status='seated',player_seat_status='seated' WHERE room_id=r.id;
  UPDATE celo_rooms SET status=CASE WHEN current_bank_sc<=0 AND banker_id IS NOT NULL THEN 'bank_takeover' ELSE 'waiting' END,bank_busted=(current_bank_sc<=0),last_round_was_celo=(p_is_celo AND a.status='banker_rolling'),banker_celo_at=CASE WHEN p_is_celo AND a.status='banker_rolling' THEN now() ELSE NULL END,last_activity=now() WHERE id=r.id RETURNING * INTO r;
  SELECT * INTO a FROM celo_rounds WHERE id=a.id;
  IF a.banker_dice_result='instant_win' THEN v_winners:=jsonb_build_array(jsonb_build_object('user_id',a.banker_id,'payout_sc',a.banker_winnings_sc,'in_table_escrow',true));
  ELSIF a.banker_dice_result='point' THEN
   SELECT COALESCE(jsonb_agg(jsonb_build_object('user_id',user_id,'payout_sc',payout_sc)),'[]'::jsonb) INTO v_winners FROM celo_player_rolls WHERE round_id=a.id AND outcome='win';
   IF a.banker_winnings_sc>0 THEN v_winners:=v_winners||jsonb_build_array(jsonb_build_object('user_id',a.banker_id,'payout_sc',a.banker_winnings_sc,'in_table_escrow',true));END IF;
  END IF;
  UPDATE celo_rounds SET settlement_snapshot=jsonb_build_object('banker_id',a.banker_id,'entries',a.entry_snapshot,'winners',v_winners,'fee_sc',a.platform_fee_sc,'bank_sc',r.current_bank_sc) WHERE id=a.id RETURNING * INTO a;
  PERFORM celo_record_platform_fee(a.id,'celo_main_fee',a.platform_fee_sc,'C-Lo main table fee',NULL,'celo:atomic:fee:'||a.id);
  PERFORM celo_settle_sidebets_atomic(r.id,a.id);
 END IF;
 UPDATE celo_rounds SET roll_seq=roll_seq+1,last_roll_dice=p_dice,last_roll_user_id=v_target,last_roll_name=p_name,last_roll_point=p_point,last_roll_outcome=v_outcome,pending_roll_id=NULL,pending_roll_user_id=NULL,pending_roll_payload=NULL,banker_roll_in_flight=false,roll_processing=false,updated_at=now() WHERE id=a.id RETURNING * INTO a;
 v_response:=jsonb_build_object('ok',true,'room',to_jsonb(r),'round',to_jsonb(a),'currentRound',to_jsonb(a),'roll',to_jsonb(v_roll),'dice',p_dice,'rollName',p_name,'result',p_result,'point',p_point,'outcome',v_outcome,'isCelo',p_is_celo,'payoutSc',v_payout,'roundComplete',v_complete,'player_can_become_banker',p_is_celo AND a.player_celo_offer,'bank_stopped',r.current_bank_sc=0,'oldBankerId',v_old_banker,'newBankerId',r.banker_id,'player_user_id',v_target,'newBalance',(SELECT gpay_coins FROM users WHERE id=p_user));
 INSERT INTO celo_action_receipts(request_id,user_id,room_id,action,input_hash,response) VALUES(p_request,p_user,r.id,'roll',md5(p_request::text),v_response);
 RETURN v_response;
END $function$

CREATE OR REPLACE FUNCTION public.celo_sidebet_action_atomic(p_user uuid, p_room uuid, p_action text, p_request uuid, p_input jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE r celo_rooms%ROWTYPE;b celo_side_bets%ROWTYPE;a celo_rounds%ROWTYPE;v_amount integer;v_type text;v_mult numeric;v_saved celo_action_receipts%ROWTYPE;v_response jsonb;v_hash text;
BEGIN
 PERFORM pg_advisory_xact_lock(hashtextextended(p_request::text,0));
 v_hash:=md5(COALESCE(p_room::text,'')||p_action||p_input::text);
 SELECT * INTO v_saved FROM celo_action_receipts WHERE request_id=p_request;
 IF FOUND THEN IF v_saved.user_id<>p_user OR v_saved.input_hash<>v_hash THEN RAISE EXCEPTION 'Request id belongs to another action'; END IF;RETURN v_saved.response;END IF;
 IF p_action='accept' THEN SELECT room_id INTO p_room FROM celo_side_bets WHERE id=(p_input->>'bet_id')::uuid; END IF;
 SELECT * INTO r FROM celo_rooms WHERE id=p_room FOR UPDATE;
 IF NOT FOUND OR r.status IN('cancelled','completed') OR r.paused_at IS NOT NULL THEN RAISE EXCEPTION 'Table is unavailable'; END IF;
 IF NOT EXISTS(SELECT 1 FROM celo_room_players WHERE room_id=r.id AND user_id=p_user) THEN RAISE EXCEPTION 'Not seated'; END IF;
 IF p_action='create' THEN
  v_amount:=(p_input->>'amount_sc')::integer;v_type:=p_input->>'bet_type';v_mult:=CASE v_type WHEN 'celo' THEN 8 WHEN 'shit' THEN 8 WHEN 'trips' THEN 8 WHEN 'hand_crack' THEN 4.5 WHEN 'banker_wins' THEN 1.8 WHEN 'player_wins' THEN 1.8 ELSE NULL END;
  IF v_amount IS NULL OR v_amount<100 OR v_amount%100<>0 OR v_mult IS NULL THEN RAISE EXCEPTION 'Invalid side entry'; END IF;
  SELECT * INTO a FROM celo_rounds WHERE id=NULLIF(p_input->>'round_id','')::uuid AND room_id=r.id FOR UPDATE;
  IF a.id IS NULL OR a.status NOT IN('banker_rolling','betting') OR a.roll_seq>0 OR a.pending_roll_id IS NOT NULL THEN RAISE EXCEPTION 'Side entries require an unrolled current round'; END IF;
  PERFORM celo_wallet_move(p_user,-v_amount,'celo:side:create:'||p_request,'celo_sidebet');
  INSERT INTO celo_side_bets(room_id,round_id,creator_id,bet_type,amount_sc,odds_multiplier,status,expires_at,creator_debit_ref) VALUES(r.id,a.id,p_user,v_type,v_amount,v_mult,'open',now()+interval '60 seconds','celo:side:create:'||p_request) RETURNING * INTO b;
 ELSIF p_action='accept' THEN
  SELECT * INTO b FROM celo_side_bets WHERE id=(p_input->>'bet_id')::uuid FOR UPDATE;
  SELECT * INTO a FROM celo_rounds WHERE id=b.round_id FOR UPDATE;
  IF b.status='matched' AND b.acceptor_id=p_user THEN RETURN jsonb_build_object('ok',true,'sideBet',to_jsonb(b),'idempotent',true); END IF;
  IF b.status<>'open' OR b.expires_at<now() OR b.creator_id=p_user OR a.status NOT IN('banker_rolling','betting') OR a.roll_seq>0 OR a.pending_roll_id IS NOT NULL THEN RAISE EXCEPTION 'Side entry is no longer available'; END IF;
  PERFORM celo_wallet_move(p_user,-b.amount_sc,'celo:side:accept:'||p_request,'celo_sidebet');
  UPDATE celo_side_bets SET acceptor_id=p_user,status='matched',acceptor_debit_ref='celo:side:accept:'||p_request WHERE id=b.id RETURNING * INTO b;
 ELSE RAISE EXCEPTION 'Invalid side action';END IF;
 v_response:=jsonb_build_object('ok',true,'sideBet',to_jsonb(b),'side_bet',to_jsonb(b));
 INSERT INTO celo_action_receipts(request_id,user_id,room_id,action,input_hash,response) VALUES(p_request,p_user,r.id,'side_'||p_action,v_hash,v_response);RETURN v_response;
END $function$

CREATE OR REPLACE FUNCTION public.celo_settle_sidebets_atomic(p_room uuid, p_round uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE r celo_rooms%ROWTYPE;a celo_rounds%ROWTYPE;b celo_side_bets%ROWTYPE;v_banker boolean;v_creator boolean;v_push boolean;v_winner uuid;v_fee integer;v_name text;
BEGIN
 SELECT * INTO r FROM celo_rooms WHERE id=p_room FOR UPDATE;
 SELECT * INTO a FROM celo_rounds WHERE id=p_round AND room_id=p_room FOR UPDATE;
 IF a.status<>'completed' THEN RETURN;END IF;
 SELECT EXISTS(SELECT 1 FROM celo_player_rolls WHERE round_id=a.id AND outcome='push') INTO v_push;
 v_banker:=CASE WHEN v_push THEN NULL WHEN a.banker_dice_result='instant_win' THEN true WHEN a.banker_dice_result='instant_loss' THEN false WHEN a.banker_dice_result='point' THEN NOT EXISTS(SELECT 1 FROM celo_player_rolls WHERE round_id=a.id AND outcome='win') ELSE NULL END;
 v_name:=upper(COALESCE(a.banker_dice_name,''));
 FOR b IN SELECT * FROM celo_side_bets WHERE room_id=r.id AND round_id=a.id AND status IN('open','matched') ORDER BY id FOR UPDATE LOOP
  v_creator:=CASE WHEN v_push OR b.status='open' THEN NULL WHEN b.bet_type='banker_wins' THEN v_banker WHEN b.bet_type='player_wins' THEN NOT v_banker WHEN b.bet_type='celo' THEN a.banker_dice_result='instant_win' AND v_name LIKE '%C-LO%' WHEN b.bet_type='trips' THEN a.banker_dice_result='instant_win' AND (v_name LIKE '%TRIP%' OR v_name LIKE '%ACE OUT%') WHEN b.bet_type='hand_crack' THEN a.banker_dice_result='instant_win' AND v_name LIKE '%HAND CRACK%' WHEN b.bet_type='shit' THEN a.banker_dice_result='instant_loss' AND (v_name LIKE '%SHIT%' OR v_name LIKE '%DICK%' OR v_name LIKE '%DICE%' OR v_name LIKE '%ACE-DEUCE-TREY%') ELSE NULL END;
  IF v_creator IS NULL THEN
   PERFORM celo_wallet_move(b.creator_id,b.amount_sc,'celo:side:void:'||b.id||':creator','celo_bank_refund');
   IF b.acceptor_id IS NOT NULL THEN PERFORM celo_wallet_move(b.acceptor_id,b.amount_sc,'celo:side:void:'||b.id||':acceptor','celo_bank_refund'); END IF;
   UPDATE celo_side_bets SET status='cancelled',winner_id=NULL,payout_sc=0,platform_fee_sc=0,settled_at=now() WHERE id=b.id;
  ELSE
   v_winner:=CASE WHEN v_creator THEN b.creator_id ELSE b.acceptor_id END;v_fee:=floor((b.amount_sc*2)*LEAST(100,GREATEST(0,r.platform_fee_pct))/100.0);
   PERFORM celo_wallet_move(v_winner,b.amount_sc*2-v_fee,'celo:side:payout:'||b.id,'celo_payout');
   PERFORM celo_record_platform_fee(a.id,'celo_side_fee',v_fee,'C-Lo side entry fee',v_winner,'celo:atomic:sidefee:'||b.id);
   UPDATE celo_side_bets SET status=CASE WHEN v_creator THEN 'won' ELSE 'lost' END,winner_id=v_winner,payout_sc=b.amount_sc*2-v_fee,platform_fee_sc=v_fee,settled_at=now() WHERE id=b.id;
  END IF;
 END LOOP;
END $function$

CREATE OR REPLACE FUNCTION public.celo_cleanup_room_atomic(p_room uuid, p_pause boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE r celo_rooms%ROWTYPE;p celo_room_players%ROWTYPE;b celo_side_bets%ROWTYPE;v_count integer;v_fee integer:=0;
BEGIN
 SELECT * INTO r FROM celo_rooms WHERE id=p_room FOR UPDATE;
 IF NOT FOUND OR r.status='cancelled' THEN RETURN jsonb_build_object('ok',true,'idempotent',true);END IF;
 IF p_pause THEN
  IF r.paused_at IS NULL OR r.pause_expires_at IS NULL OR r.pause_expires_at>now() THEN RAISE EXCEPTION 'Pause has not expired';END IF;
 ELSE
  IF r.paused_at IS NOT NULL OR r.last_activity>now()-interval '10 minutes' THEN RAISE EXCEPTION 'Table is not abandoned';END IF;
 END IF;
 SELECT count(*) INTO v_count FROM celo_room_players WHERE room_id=r.id AND role='player' AND entry_posted AND stake_amount_sc>0;
 IF NOT p_pause AND v_count=0 THEN RETURN jsonb_build_object('ok',false,'reason','no_posted_players');END IF;
 -- Same room -> round -> wallet order as rolls; cancellation cannot interleave settlement.
 PERFORM 1 FROM celo_rounds WHERE room_id=r.id AND status IN('banker_rolling','player_rolling','betting') ORDER BY round_number FOR UPDATE;
 FOR p IN SELECT * FROM celo_room_players WHERE room_id=r.id AND role='player' AND entry_posted AND stake_amount_sc>0 ORDER BY user_id FOR UPDATE LOOP
  PERFORM celo_wallet_move(p.user_id,p.stake_amount_sc,'celo:cleanup:entry:'||r.id||':'||p.user_id,'celo_bank_refund');
 END LOOP;
 FOR b IN SELECT * FROM celo_side_bets WHERE room_id=r.id AND status IN('open','matched') ORDER BY id FOR UPDATE LOOP
  PERFORM celo_wallet_move(b.creator_id,b.amount_sc,'celo:cleanup:side:'||b.id||':creator','celo_bank_refund');
  IF b.acceptor_id IS NOT NULL THEN PERFORM celo_wallet_move(b.acceptor_id,b.amount_sc,'celo:cleanup:side:'||b.id||':acceptor','celo_bank_refund');END IF;
  UPDATE celo_side_bets SET status='cancelled',settled_at=now() WHERE id=b.id;
 END LOOP;
 IF v_count>0 AND (NOT p_pause OR r.paused_by=r.banker_id) THEN
  SELECT LEAST(500,GREATEST(0,gpay_coins)) INTO v_fee FROM users WHERE id=r.banker_id FOR UPDATE;
  PERFORM celo_wallet_move(r.banker_id,-v_fee,'celo:cleanup:fee:'||r.id,'celo_abandon_fee');
  IF v_fee>0 THEN PERFORM celo_record_platform_fee(NULL,'celo_abandon_fee',v_fee,'C-Lo abandonment fee',r.banker_id,'celo:atomic:cleanupfee:'||r.id);END IF;
 END IF;
 PERFORM celo_wallet_move(r.banker_id,r.current_bank_sc,'celo:cleanup:bank:'||r.id,'celo_bank_refund');
 UPDATE celo_rounds SET status='cancelled',completed_at=now(),pending_roll_id=NULL,pending_roll_user_id=NULL,pending_roll_payload=NULL,roll_processing=false,banker_roll_in_flight=false WHERE room_id=r.id AND status IN('banker_rolling','player_rolling','betting');
 UPDATE celo_room_players SET entry_sc=0,bet_cents=0,stake_amount_sc=0,entry_posted=false,status='seated',player_seat_status='seated' WHERE room_id=r.id;
 DELETE FROM celo_pause_votes WHERE room_id=r.id;
 UPDATE celo_rooms SET status='cancelled',current_bank_sc=0,current_bank_cents=0,abandoned_at=now(),abandonment_fee_charged=(v_fee>0),paused_at=NULL,paused_by=NULL,pause_reason=NULL,pause_expires_at=NULL,last_activity=now() WHERE id=r.id;
 RETURN jsonb_build_object('ok',true,'feeCharged',v_fee);
END $function$

CREATE OR REPLACE FUNCTION public.celo_recover_due_actions()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
 SET lock_timeout TO '2s'
AS $function$
DECLARE a celo_rounds%ROWTYPE;r celo_rooms%ROWTYPE;v_payload jsonb;v_actor uuid;v_request uuid;v_dice integer[];v_count integer:=0;v_errors integer:=0;
BEGIN
 FOR a IN SELECT * FROM celo_rounds WHERE status IN('banker_rolling','player_rolling') AND ((pending_roll_id IS NOT NULL AND roll_animation_start_at<now()-interval '30 seconds') OR (status='player_rolling' AND player_roll_deadline_at<now() AND pending_roll_id IS NULL)) ORDER BY room_id LIMIT 25 LOOP
  BEGIN
   SELECT * INTO r FROM celo_rooms WHERE id=a.room_id;
   IF r.status='cancelled' OR r.paused_at IS NOT NULL THEN CONTINUE;END IF;
   IF a.pending_roll_id IS NOT NULL THEN
    v_payload:=a.pending_roll_payload;v_request:=a.pending_roll_id;v_actor:=COALESCE(a.pending_roll_user_id,CASE WHEN a.status='banker_rolling' THEN r.banker_id ELSE a.roller_user_id END);
    IF v_payload IS NULL THEN RAISE EXCEPTION 'Accepted roll has no trusted payload';END IF;
    SELECT array_agg(d::integer) INTO v_dice FROM jsonb_array_elements_text(CASE WHEN v_payload->'dice'='null'::jsonb THEN '[]'::jsonb ELSE v_payload->'dice' END) d;
    PERFORM celo_settle_roll_atomic(v_actor,r.id,a.id,v_request,v_dice,v_payload->>'result',v_payload->>'rollName',(v_payload->>'point')::integer,(v_payload->>'isCelo')::boolean,v_payload->'dice'='null'::jsonb);
   ELSE
    v_request:=gen_random_uuid();v_payload:=jsonb_build_object('dice',NULL,'result','instant_loss','rollName','TIMEOUT — FORFEIT','point',NULL,'isCelo',false);
    PERFORM celo_claim_roll_atomic(r.banker_id,r.id,a.id,v_request,NULL,true,v_payload);
    PERFORM celo_settle_roll_atomic(r.banker_id,r.id,a.id,v_request,NULL,'instant_loss','TIMEOUT — FORFEIT',NULL,false,true);
   END IF;
   v_count:=v_count+1;
  EXCEPTION WHEN OTHERS THEN v_errors:=v_errors+1;RAISE WARNING 'C-Lo recovery skipped round %: %',a.id,SQLERRM;
  END;
 END LOOP;
 FOR r IN SELECT * FROM celo_rooms WHERE status<>'cancelled' AND ((paused_at IS NOT NULL AND pause_expires_at<now()) OR (paused_at IS NULL AND last_activity<now()-interval '10 minutes' AND EXISTS(SELECT 1 FROM celo_room_players p WHERE p.room_id=celo_rooms.id AND p.role='player' AND p.entry_posted AND p.stake_amount_sc>0))) ORDER BY id LIMIT 25 LOOP
  BEGIN
   PERFORM celo_cleanup_room_atomic(r.id,r.paused_at IS NOT NULL);v_count:=v_count+1;
  EXCEPTION WHEN OTHERS THEN v_errors:=v_errors+1;RAISE WARNING 'C-Lo cleanup skipped room %: %',r.id,SQLERRM;
  END;
 END LOOP;
 RETURN jsonb_build_object('processed',v_count,'errors',v_errors);
END $function$

CREATE OR REPLACE FUNCTION public.celo_reconcile_terminal_room_bank(p_round_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  r RECORD;
  v_delta integer;
  v_new_bank integer;
BEGIN
  IF p_round_id IS NULL THEN
    RETURN jsonb_build_object('reconciled', false, 'reason', 'missing_round_id');
  END IF;

  SELECT
    id,
    room_id,
    status,
    banker_dice_result,
    banker_winnings_sc,
    terminal_bank_delta_sc,
    terminal_room_bank_applied
  INTO r
  FROM public.celo_rounds
  WHERE id = p_round_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('reconciled', false, 'reason', 'round_not_found');
  END IF;

  IF r.status <> 'completed' THEN
    RETURN jsonb_build_object('reconciled', false, 'reason', 'round_not_completed');
  END IF;

  IF r.terminal_room_bank_applied IS TRUE THEN
    RETURN jsonb_build_object(
      'reconciled', false,
      'reason', 'already_applied',
      'new_bank_sc', (
        SELECT COALESCE(current_bank_sc, 0)::integer FROM public.celo_rooms WHERE id = r.room_id
      )
    );
  END IF;

  v_delta := r.terminal_bank_delta_sc;
  IF v_delta IS NULL THEN
    RETURN jsonb_build_object(
      'reconciled', false,
      'reason', 'no_stored_delta_set_terminal_bank_delta_sc_manually'
    );
  END IF;

  IF v_delta = 0 THEN
    UPDATE public.celo_rounds SET terminal_room_bank_applied = true WHERE id = p_round_id;
    RETURN jsonb_build_object(
      'reconciled', true,
      'reason', 'zero_delta_marked',
      'new_bank_sc', (
        SELECT COALESCE(current_bank_sc, 0)::integer FROM public.celo_rooms WHERE id = r.room_id
      )
    );
  END IF;

  UPDATE public.celo_rooms AS c
  SET
    current_bank_sc = GREATEST(0, COALESCE(c.current_bank_sc, 0) + v_delta),
    current_bank_cents = GREATEST(0, COALESCE(c.current_bank_sc, 0) + v_delta)
  WHERE c.id = r.room_id
  RETURNING c.current_bank_sc INTO v_new_bank;

  UPDATE public.celo_rounds
  SET terminal_room_bank_applied = true,
      terminal_bank_delta_sc = COALESCE(terminal_bank_delta_sc, v_delta)
  WHERE id = p_round_id;

  RETURN jsonb_build_object(
    'reconciled', true,
    'reason', 'applied',
    'new_bank_sc', COALESCE(v_new_bank, 0)
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.celo_record_platform_fee(p_round_id uuid, p_fee_type text, p_amount_cents integer, p_description text, p_user_id uuid DEFAULT NULL::uuid, p_idempotency_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_amount integer := GREATEST(0, COALESCE(p_amount_cents, 0));
  v_fee_type text := COALESCE(NULLIF(trim(p_fee_type), ''), 'celo_main_fee');
  v_desc text := COALESCE(NULLIF(trim(p_description), ''), 'C-Lo platform fee');
  v_key text := COALESCE(
    NULLIF(trim(p_idempotency_key), ''),
    CASE
      WHEN p_round_id IS NULL THEN NULL
      ELSE 'celo_fee:' || p_round_id::text || ':' || v_fee_type
    END
  );
  v_inserted_id uuid;
BEGIN
  IF v_amount <= 0 THEN
    RETURN jsonb_build_object('inserted', false, 'reason', 'non_positive_amount');
  END IF;
  IF v_key IS NULL THEN
    RETURN jsonb_build_object('inserted', false, 'reason', 'idempotency_key_required');
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.platform_earnings pe WHERE pe.idempotency_key = v_key
  ) THEN
    RETURN jsonb_build_object('inserted', false, 'idempotency_key', v_key);
  END IF;

  BEGIN
    INSERT INTO public.platform_earnings (
      source,
      source_id,
      amount_cents,
      description,
      user_id,
      round_id,
      fee_type,
      idempotency_key
    )
    VALUES (
      'celo_game',
      CASE WHEN p_round_id IS NULL THEN NULL ELSE p_round_id::text END,
      v_amount,
      v_desc,
      p_user_id,
      p_round_id,
      v_fee_type,
      v_key
    )
    RETURNING id INTO v_inserted_id;
  EXCEPTION
    WHEN unique_violation THEN
      RETURN jsonb_build_object('inserted', false, 'idempotency_key', v_key);
  END;

  PERFORM public.platform_record_revenue(v_amount, 'celo_fee');

  RETURN jsonb_build_object('inserted', true, 'id', v_inserted_id, 'idempotency_key', v_key);
END;
$function$
